import React, { useEffect, useMemo, useState } from "react";
import { buildRangeReport } from "../utils/reports";

const formatCurrency = (val) =>
  new Intl.NumberFormat("en-PH", { style: "currency", currency: "PHP", maximumFractionDigits: 0 }).format(val || 0);

const METHOD_META = [
  { key: "cash", label: "Cash", color: "bg-emerald-500", ring: "ring-emerald-200" },
  { key: "gcash", label: "GCash", color: "bg-sky-500", ring: "ring-sky-200" },
  { key: "gotyme", label: "GoTyme", color: "bg-purple-500", ring: "ring-purple-200" },
  { key: "bank", label: "Bank", color: "bg-teal-500", ring: "ring-teal-200" },
  { key: "notPaid", label: "Unpaid", color: "bg-amber-500", ring: "ring-amber-200" },
  { key: "free", label: "Free", color: "bg-slate-400", ring: "ring-slate-200" },
];

const RANGE_LABELS = { day: "Today", week: "This Week", month: "This Month" };

function PaymentBreakdownTable({ rows, emptyMessage }) {
  if (!rows.length) {
    return (
      <div className="py-10 text-center text-sm text-slate-400">{emptyMessage}</div>
    );
  }

  const sorted = [...rows].sort((a, b) => {
    const dateCmp = (b.date || "").localeCompare(a.date || "");
    if (dateCmp !== 0) return dateCmp;
    return (b.amount || 0) - (a.amount || 0);
  });

  return (
    <div className="border border-slate-100 rounded-xl overflow-hidden">
      <table className="w-full text-left text-sm">
        <thead className="bg-slate-50 text-[10px] font-bold uppercase tracking-wide text-slate-500">
          <tr>
            <th className="py-2.5 px-3">Name</th>
            <th className="py-2.5 px-3">Date</th>
            <th className="py-2.5 px-3 hidden sm:table-cell">Details</th>
            <th className="py-2.5 px-3 text-right">Amount</th>
          </tr>
        </thead>
        <tbody className="divide-y divide-slate-100">
          {sorted.map((row) => (
            <tr key={row.id} className="hover:bg-slate-50/80">
              <td className="py-2.5 px-3 font-semibold text-slate-900">{row.name}</td>
              <td className="py-2.5 px-3 text-xs font-mono text-slate-500 whitespace-nowrap">{row.date}</td>
              <td className="py-2.5 px-3 text-xs text-slate-500 hidden sm:table-cell">{row.context}</td>
              <td className="py-2.5 px-3 text-right font-bold text-slate-900">{formatCurrency(row.amount)}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

export default function RevenueDetailModal({
  isOpen,
  onClose,
  initialRange = "day",
  reportDate,
  opSessions = [],
  bookingsV2 = {},
  slotsV2 = {},
  settings = {},
  players = [],
}) {
  const [modalRange, setModalRange] = useState(initialRange);
  const [selectedMethod, setSelectedMethod] = useState(null);
  const [detailTab, setDetailTab] = useState("rentals");

  useEffect(() => {
    if (isOpen) {
      setModalRange(initialRange);
      setSelectedMethod(null);
      setDetailTab("rentals");
    }
  }, [isOpen, initialRange]);

  const data = useMemo(() => {
    if (!isOpen) return null;
    return buildRangeReport(modalRange, reportDate, opSessions, bookingsV2, slotsV2, settings, players);
  }, [isOpen, modalRange, reportDate, opSessions, bookingsV2, slotsV2, settings, players]);

  const aggregatedPayments = useMemo(() => {
    if (!data?.payments) return [];
    return METHOD_META.map((meta) => {
      const op = data.payments.openPlay[meta.key] || { count: 0, amount: 0 };
      const ren = data.payments.rentals[meta.key] || { count: 0, amount: 0 };
      return {
        ...meta,
        totalCount: (op.count || 0) + (ren.count || 0),
        totalAmount: (op.amount || 0) + (ren.amount || 0),
      };
    });
  }, [data]);

  const filteredDetails = useMemo(() => {
    if (!selectedMethod || !data?.paymentDetails) {
      return { openPlay: [], rentals: [] };
    }
    const filterByBucket = (rows) =>
      (rows || []).filter((r) => r.bucket === selectedMethod);
    return {
      openPlay: filterByBucket(data.paymentDetails.openPlay),
      rentals: filterByBucket(data.paymentDetails.rentals),
    };
  }, [data, selectedMethod]);

  const activeTabRows = detailTab === "openPlay" ? filteredDetails.openPlay : filteredDetails.rentals;
  const activeTabTotal = activeTabRows.reduce((sum, r) => sum + (r.amount || 0), 0);
  const selectedLabel = METHOD_META.find((m) => m.key === selectedMethod)?.label || "";

  if (!isOpen || !data) return null;

  const totalIncome = (data.openPlay?.totalIncome || 0) + (data.rentals?.totalIncome || 0);

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 backdrop-blur-sm p-4 animate-in fade-in duration-200">
      <div className="bg-white rounded-2xl shadow-2xl max-w-3xl w-full overflow-hidden flex flex-col max-h-[92vh]">
        <div className="p-5 border-b border-gray-100 flex justify-between items-start bg-white sticky top-0 z-10 gap-4">
          <div>
            <h2 className="text-lg font-bold text-slate-900">Revenue Details</h2>
            <p className="text-xs text-slate-500 uppercase tracking-wide">{RANGE_LABELS[modalRange]} Report</p>
          </div>
          <div className="flex items-center gap-2">
            <div className="flex bg-slate-100 p-1 rounded-lg">
              {["day", "week", "month"].map((r) => (
                <button
                  key={r}
                  type="button"
                  onClick={() => {
                    setModalRange(r);
                    setSelectedMethod(null);
                  }}
                  className={`px-3 py-1 rounded-md text-[10px] font-bold transition-all ${
                    modalRange === r
                      ? "bg-white text-slate-900 shadow-sm"
                      : "text-slate-500 hover:text-slate-700"
                  }`}
                >
                  {r === "day" ? "Day" : r === "week" ? "Week" : "Month"}
                </button>
              ))}
            </div>
            <button
              type="button"
              onClick={onClose}
              className="p-2 rounded-full hover:bg-slate-100 text-slate-500 transition-colors"
            >
              ✕
            </button>
          </div>
        </div>

        <div className="p-6 overflow-y-auto flex-1">
          <div className="text-center mb-6">
            <p className="text-sm text-slate-500 mb-1">Total Income</p>
            <h1 className="text-4xl font-bold text-slate-900 tracking-tight">{formatCurrency(totalIncome)}</h1>
          </div>

          <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-3">
            Breakdown by Payment Method
          </h3>
          <p className="text-[11px] text-slate-400 mb-3">Tap a method to see names and amounts.</p>
          <div className="space-y-2">
            {aggregatedPayments.map((p) => {
              const isActive = selectedMethod === p.key;
              return (
                <button
                  key={p.key}
                  type="button"
                  onClick={() => {
                    setSelectedMethod(isActive ? null : p.key);
                    setDetailTab("rentals");
                  }}
                  className={`w-full flex items-center justify-between p-3 rounded-lg border transition-colors text-left ${
                    isActive
                      ? `border-slate-300 bg-white ring-2 ${p.ring}`
                      : "border-slate-50 hover:border-slate-100 bg-slate-50/50"
                  }`}
                >
                  <div className="flex items-center gap-3">
                    <div className={`w-2.5 h-2.5 rounded-full ${p.color}`} />
                    <span className="font-medium text-slate-700 text-sm">{p.label}</span>
                  </div>
                  <div className="text-right">
                    <div className="text-sm font-bold text-slate-900">{formatCurrency(p.totalAmount)}</div>
                    <div className="text-[10px] text-slate-400">{p.totalCount} transactions</div>
                  </div>
                </button>
              );
            })}
          </div>

          {selectedMethod && (
            <div className="mt-8 pt-6 border-t border-slate-100 animate-in slide-in-from-bottom-2 duration-200">
              <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3 mb-4">
                <div>
                  <h3 className="text-sm font-bold text-slate-900">{selectedLabel} Breakdown</h3>
                  <p className="text-xs text-slate-500">{RANGE_LABELS[modalRange]} · by name</p>
                </div>
                <div className="flex bg-slate-100 p-1 rounded-lg self-start">
                  {[
                    { id: "rentals", label: "Rentals" },
                    { id: "openPlay", label: "Open Play" },
                  ].map((tab) => (
                    <button
                      key={tab.id}
                      type="button"
                      onClick={() => setDetailTab(tab.id)}
                      className={`px-3 py-1.5 rounded-md text-xs font-bold transition-all ${
                        detailTab === tab.id
                          ? "bg-white text-slate-900 shadow-sm"
                          : "text-slate-500 hover:text-slate-700"
                      }`}
                    >
                      {tab.label}
                      <span className="ml-1 text-[10px] font-normal text-slate-400">
                        ({(filteredDetails[tab.id] || []).length})
                      </span>
                    </button>
                  ))}
                </div>
              </div>

              <div className="mb-3 flex items-center justify-between text-xs">
                <span className="text-slate-500">
                  {activeTabRows.length} {activeTabRows.length === 1 ? "entry" : "entries"}
                </span>
                <span className="font-bold text-slate-900">Subtotal: {formatCurrency(activeTabTotal)}</span>
              </div>

              <PaymentBreakdownTable
                rows={activeTabRows}
                emptyMessage={`No ${selectedLabel.toLowerCase()} ${detailTab === "openPlay" ? "open play" : "rental"} payments for ${RANGE_LABELS[modalRange].toLowerCase()}.`}
              />
            </div>
          )}

          <div className="mt-8 pt-6 border-t border-slate-100">
            <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-3">Sources</h3>
            <div className="grid grid-cols-2 gap-4">
              <div className="p-3 bg-indigo-50 rounded-lg">
                <div className="text-xs text-indigo-600 font-medium mb-1">Open Play</div>
                <div className="text-lg font-bold text-indigo-900">{formatCurrency(data.openPlay.totalIncome)}</div>
              </div>
              <div className="p-3 bg-emerald-50 rounded-lg">
                <div className="text-xs text-emerald-600 font-medium mb-1">Rentals</div>
                <div className="text-lg font-bold text-emerald-900">{formatCurrency(data.rentals.totalIncome)}</div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
