import React from 'react';

export default function RentalPromoBreakdown({ pricing }) {
  if (!pricing?.promo) return null;
  return <div className="rounded-lg border border-emerald-200 bg-emerald-50 p-3 text-xs text-emerald-900" role="status">
    <p className="font-semibold">Court rental promo · Mon–Thu, 8 a.m.–5 p.m.</p>
    <p>Every 2 eligible court-hours ₱600 · single court-hour ₱400 · accumulated across courts</p>
    <p>{pricing.promo.eligibleHours} eligible court-hours in this booking</p>
    <dl className="mt-2 space-y-1">
      <div className="flex justify-between"><dt>Regular rental</dt><dd>₱{pricing.regularCourtSubtotal.toLocaleString()}</dd></div>
      <div className="flex justify-between"><dt>Promo savings</dt><dd>−₱{pricing.promoSavings.toLocaleString()}</dd></div>
      <div className="flex justify-between font-semibold"><dt>Rental subtotal</dt><dd>₱{pricing.courtSubtotal.toLocaleString()}</dd></div>
    </dl>
  </div>;
}
