import React, { useEffect, useState } from "react";
import toast from "react-hot-toast";
import { getVoicesSafe } from "../../../common/utils/tts";
import { getVoiceSync, hydrateVoiceSettings, saveVoiceSettings, subscribeVoice } from "../../../state/voiceSettings";

export default function VoicePicker({ onChange }) {
  const initial = getVoiceSync();
  const [voices, setVoices] = useState([]);
  const [voiceName, setVoiceName] = useState(() => initial.voiceName);
  const [rate, setRate] = useState(() => initial.rate);
  const [pitch, setPitch] = useState(() => initial.pitch);

  useEffect(() => {
    const load = () => setVoices(getVoicesSafe());
    load();
    // some browsers populate voices asynchronously
    window.speechSynthesis?.addEventListener?.("voiceschanged", load);
    return () => window.speechSynthesis?.removeEventListener?.("voiceschanged", load);
  }, []);

  useEffect(() => subscribeVoice((voice) => {
    setVoiceName(voice.voiceName || "");
    setRate(Number(voice.rate));
    setPitch(Number(voice.pitch));
  }), []);

  useEffect(() => {
    hydrateVoiceSettings().catch(() => {});
  }, []);

  useEffect(() => {
    onChange?.({ voiceName, rate, pitch });
    void saveVoiceSettings({ voiceName, rate, pitch }).catch(() => {
      toast.error(
        "Could not save voice settings in this browser. Check that site data is allowed.",
        { id: "voice-prefs-save-fail" }
      );
    });
  }, [voiceName, rate, pitch, onChange]);

  return (
    <div className="flex flex-wrap items-center gap-2 text-sm">
      <select
        className="border rounded px-2 py-1"
        value={voiceName}
        onChange={(e) => setVoiceName(e.target.value)}
      >
        <option value="">System Default</option>
        {voices.map((v) => (
          <option key={`${v.name}-${v.lang}`} value={v.name}>
            {v.name} ({v.lang})
          </option>
        ))}
      </select>
      <label className="flex items-center gap-1">
        Rate
        <input
          type="range" min="0.6" max="1.2" step="0.05"
          value={rate} onChange={(e) => setRate(Number(e.target.value))}
        />
        <span>{rate.toFixed(2)}</span>
      </label>
      <label className="flex items-center gap-1">
        Pitch
        <input
          type="range" min="0.8" max="1.2" step="0.05"
          value={pitch} onChange={(e) => setPitch(Number(e.target.value))}
        />
        <span>{pitch.toFixed(2)}</span>
      </label>
    </div>
  );
}
