// Utility helpers for dashboard and history analytics

const toYMD = toYMDLocal;

const formatNumber = (value) => (Number.isFinite(value) ? value : 0);

/** Booking-level rental payment (discount-aware); dedupe via countedIds Set. */
const pushBookingRentalPayment = (bookingsV2, bookingId, slotsV2, list, countedIds) => {
  if (!bookingId || countedIds.has(bookingId)) return;
  countedIds.add(bookingId);
  const booking = bookingsV2[bookingId];
  if (!isRentalBooking(booking)) return;
  const pSum = booking.paymentSummary || {};
  const { totalDue, amountPaid, balance } = getRentalBookingFinancials(booking, slotsV2);
  if (amountPaid > 0) {
    list.push({
      status: "paid",
      amount: amountPaid,
      paymentMethod: pSum.paymentMethod || "CASH",
    });
  }
  if (balance > 0) {
    list.push({
      status: "unpaid",
      amount: balance,
      paymentMethod: null,
    });
  } else if (amountPaid <= 0 && totalDue > 0) {
    list.push({
      status: "unpaid",
      amount: totalDue,
      paymentMethod: null,
    });
  }
};

const bookingRentalIncome = (bookingsV2, bookingId, slotsV2, dayYmd = null) => {
  const booking = bookingsV2[bookingId];
  if (!isRentalBooking(booking)) return 0;
  if (dayYmd) return attributeRentalPaidToYmd(booking, slotsV2, dayYmd);
  return booking?.paymentSummary?.amountPaid || 0;
};

const slotDurationHours = slotCourtHours;

const UNKNOWN_RENTER_KEY = "__unknown_renter__";

const getRenterDisplayName = (booking) => {
  const raw = String(booking?.renter?.name || booking?.title || "").trim();
  return raw || "Unknown Renter";
};

const getRenterGroupKey = (booking) => {
  const raw = String(booking?.renter?.name || booking?.title || "").trim();
  return raw ? raw.toLowerCase() : UNKNOWN_RENTER_KEY;
};

/** Aggregate rental stats per client for slots in range (booking-level dedupe). */
export const buildRentalClientStats = (
  bookingsV2 = {},
  slotsInRange = [],
  slotsV2 = {},
  { limit = null } = {}
) => {
  const byKey = new Map();

  slotsInRange.forEach((slot) => {
    if (!slot || slot.status === "CANCELLED") return;
    const booking = bookingsV2[slot.bookingId];
    if (!booking || !isRentalBooking(booking)) return;

    const key = getRenterGroupKey(booking);
    if (!byKey.has(key)) {
      byKey.set(key, {
        key,
        displayName: getRenterDisplayName(booking),
        contact: booking.renter?.contact || booking.renter?.email || "",
        bookingIds: new Set(),
        courtHours: 0,
        amountPaid: 0,
        totalDue: 0,
        balance: 0,
      });
    }

    const row = byKey.get(key);
    row.courtHours += slotDurationHours(slot);
    if (!row.contact && (booking.renter?.contact || booking.renter?.email)) {
      row.contact = booking.renter?.contact || booking.renter?.email || "";
    }

    if (!row.bookingIds.has(booking.id)) {
      row.bookingIds.add(booking.id);
      const { amountPaid, totalDue, balance } = getRentalBookingFinancials(booking, slotsV2);
      row.amountPaid += amountPaid;
      row.totalDue += totalDue;
      row.balance += balance;
    }
  });

  const sorted = Array.from(byKey.values())
    .map((row) => ({
      key: row.key,
      displayName: row.displayName,
      contact: row.contact,
      bookingCount: row.bookingIds.size,
      courtHours: row.courtHours,
      amountPaid: row.amountPaid,
      totalDue: row.totalDue,
      balance: row.balance,
    }))
    .sort((a, b) => {
      // Top rental clients = cash collected (amountPaid), not due / booking volume
      if (b.amountPaid !== a.amountPaid) return b.amountPaid - a.amountPaid;
      if (b.bookingCount !== a.bookingCount) return b.bookingCount - a.bookingCount;
      return a.displayName.localeCompare(b.displayName);
    });

  return limit != null && limit > 0 ? sorted.slice(0, limit) : sorted;
};

export const buildPerPlayerMatchStats = (matches = []) => {
  const results = [];

  matches.forEach((match) => {
    if (!match) return;
    const { id: matchId, winner, teams } = match;
    const greenIds = Array.isArray(teams?.green) ? teams.green : [];
    const blueIds = Array.isArray(teams?.blue) ? teams.blue : [];

    const greenResult = winner === "green" ? "win" : winner === "blue" ? "loss" : "tie";
    const blueResult = winner === "blue" ? "win" : winner === "green" ? "loss" : "tie";

    greenIds.forEach((playerId) => {
      results.push({
        playerId,
        matchId,
        result: greenResult,
        plusMinus: greenResult === "win" ? 1 : greenResult === "loss" ? -1 : 0,
      });
    });

    blueIds.forEach((playerId) => {
      results.push({
        playerId,
        matchId,
        result: blueResult,
        plusMinus: blueResult === "win" ? 1 : blueResult === "loss" ? -1 : 0,
      });
    });
  });

  return results;
};

export const buildPerPlayerWaitBeforeMatch = (matches = []) => {
  const perPlayerMatches = new Map();

  matches.forEach((match) => {
    if (!match) return;
    const lineupIds = Array.isArray(match.lineup)
      ? match.lineup.map((p) => p.id).filter(Boolean)
      : [];
    lineupIds.forEach((playerId) => {
      if (!perPlayerMatches.has(playerId)) perPlayerMatches.set(playerId, []);
      perPlayerMatches.get(playerId).push(match);
    });
  });

  const result = new Map(); // Map<playerId, Map<matchId, waitBeforeMs>>

  perPlayerMatches.forEach((playerMatches, playerId) => {
    const sorted = [...playerMatches].sort(
      (a, b) => (a.startTime || 0) - (b.startTime || 0)
    );
    let prevEnd = null;
    sorted.forEach((match) => {
      const start = formatNumber(match.startTime) || null;
      const end = formatNumber(match.endTime) || start;
      let waitMs = 0;
      if (prevEnd != null && start != null && start > prevEnd) {
        waitMs = start - prevEnd;
      }
      if (!result.has(playerId)) result.set(playerId, new Map());
      result.get(playerId).set(match.id, waitMs);
      prevEnd = end ?? prevEnd;
    });
  });

  return result;
};

export const aggregatePayments = (items = [], getStatusAndAmount) => {
  const breakdown = {
    cash: { count: 0, amount: 0 },
    gcash: { count: 0, amount: 0 },
    gotyme: { count: 0, amount: 0 },
    bank: { count: 0, amount: 0 },
    free: { count: 0, amount: 0 },
    notPaid: { count: 0, amount: 0 },
    cancelled: { count: 0, amount: 0 },
  };

  items.forEach((item) => {
    if (!item) return;
    const { status, amount, paymentMethod } = getStatusAndAmount(item) || {};
    const value = typeof amount === "number" ? amount : 0;

    const statusStr = String(status || "not_paid").toLowerCase();
    const methodStr = String(item.paymentMethod || paymentMethod || "").toLowerCase();
    const paymentKey = methodStr || statusStr;

    // Classification Logic
    if (statusStr === "cancelled") {
      breakdown.cancelled.count += 1;
      breakdown.cancelled.amount += value;
      return;
    }

    if (statusStr === "unpaid" || statusStr === "not_paid" || statusStr === "" || (!statusStr && !methodStr)) {
      breakdown.notPaid.count += 1;
      breakdown.notPaid.amount += value;
      return;
    }

    // Process Paid/Free items
    if (paymentKey === "free" || statusStr === "free") {
      breakdown.free.count += 1;
      breakdown.free.amount += value;
    } else if (paymentKey.includes("gcash")) {
      breakdown.gcash.count += 1;
      breakdown.gcash.amount += value;
    } else if (paymentKey.includes("gotyme")) {
      breakdown.gotyme.count += 1;
      breakdown.gotyme.amount += value;
    } else if (paymentKey.includes("bank")) {
      breakdown.bank.count += 1;
      breakdown.bank.amount += value;
    } else {
      // Default to Cash if 'paid' but no specific method, or actual 'cash' method
      breakdown.cash.count += 1;
      breakdown.cash.amount += value;
    }
  });

  return breakdown;
};

/** Bucket key aligned with aggregatePayments (cash, gcash, gotyme, bank, free, notPaid). */
export const classifyPaymentBucket = (status, paymentMethod = null) => {
  const statusStr = String(status || "not_paid").toLowerCase();
  const methodStr = String(paymentMethod || "").toLowerCase();
  const paymentKey = methodStr || statusStr;

  if (statusStr === "cancelled") return null;

  if (
    statusStr === "unpaid" ||
    statusStr === "not_paid" ||
    statusStr === "" ||
    (!statusStr && !methodStr)
  ) {
    return "notPaid";
  }

  if (paymentKey === "free" || statusStr === "free") return "free";
  if (paymentKey.includes("gcash")) return "gcash";
  if (paymentKey.includes("gotyme")) return "gotyme";
  if (paymentKey.includes("bank")) return "bank";
  return "cash";
};

const formatSlotTime = (val) => {
  if (val == null) return "";
  if (typeof val === "number") return formatMinutesAmpm(val);
  return new Date(val).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", hour12: true });
};

/** Detailed payment rows for revenue drill-down (Open Play + Rentals). */
export const collectPaymentDetails = (
  sessions = [],
  bookingsV2 = {},
  slotsInRange = [],
  slotsV2 = {}
) => {
  const openPlay = [];
  const rentals = [];

  sessions.forEach((session) => {
    if (!session) return;
    const date = toYMD(session.startedAt || session.endedAt || 0);
    const sessionLabel = session.title || session.name || "Open Play";
    (session.players || []).forEach((p) => {
      const bucket = classifyPaymentBucket(p.paymentStatus, p.paymentMethod);
      if (!bucket) return;
      const amount = typeof p.price === "number" ? p.price : 0;
      openPlay.push({
        id: `${session.id}-${p.id}`,
        source: "openPlay",
        name: p.name || "Unknown Player",
        amount,
        bucket,
        date,
        context: sessionLabel,
      });
    });
  });

  const bookingsInRange = new Set(slotsInRange.map((s) => s.bookingId).filter(Boolean));
  bookingsInRange.forEach((bookingId) => {
    const booking = bookingsV2[bookingId];
    if (!booking || !isRentalBooking(booking)) return;

    const bookingSlots = slotsInRange.filter((s) => s.bookingId === bookingId);
    if (bookingSlots.length === 0) return;

    const datedSlots = [...bookingSlots].sort((a, b) => {
      const d = (a.date || "").localeCompare(b.date || "");
      if (d !== 0) return d;
      return (a.startTime || 0) - (b.startTime || 0);
    });
    const start = datedSlots[0];
    const end = datedSlots[datedSlots.length - 1];
    const date = start.date || toYMD(start.startTime);
    const courtIds = [...new Set(datedSlots.map((s) => s.courtId))].sort().join(", ");
    const timeRange = `${formatSlotTime(start.startTime)} - ${formatSlotTime(end.endTime)}`;
    const context = `Court ${courtIds} · ${timeRange}`;

    const name = booking.renter?.name || booking.title || "Unknown Renter";
    const pSum = booking.paymentSummary || {};
    const { totalDue, amountPaid, balance } = getRentalBookingFinancials(booking, slotsV2);

    if (amountPaid > 0) {
      rentals.push({
        id: `${bookingId}-paid`,
        source: "rental",
        name,
        amount: amountPaid,
        bucket: classifyPaymentBucket("paid", pSum.paymentMethod),
        date,
        context,
      });
    }

    if (balance > 0) {
      rentals.push({
        id: `${bookingId}-balance`,
        source: "rental",
        name,
        amount: balance,
        bucket: "notPaid",
        date,
        context: `${context} · balance`,
      });
    } else if (amountPaid <= 0 && totalDue > 0) {
      rentals.push({
        id: `${bookingId}-unpaid`,
        source: "rental",
        name,
        amount: totalDue,
        bucket: "notPaid",
        date,
        context,
      });
    } else if (totalDue <= 0 && amountPaid <= 0) {
      rentals.push({
        id: `${bookingId}-free`,
        source: "rental",
        name,
        amount: 0,
        bucket: "free",
        date,
        context,
      });
    }
  });

  return { openPlay, rentals, all: [...openPlay, ...rentals] };
};

export const buildDailyReport = (opSessions = [], bookingsV2 = {}, slotsV2 = {}, date = new Date(), globalPlayers = []) => {
  const targetYMD = toYMD(date);

  // Exclude cancelled sessions from income and unpaid counts per business rules
  const sessionsToday = (opSessions || []).filter((s) => {
    if (!isReportableOpSession(s)) return false;
    const base = s.startedAt || s.endedAt || 0;
    return toYMD(base) === targetYMD;
  });

  // Open Play aggregates
  let totalPlayers = 0;
  // Income should include paid methods with a collectible amount.
  let totalIncome = 0;
  const playerStats = new Map();
  const allMatches = [];

  sessionsToday.forEach((session) => {
    const players = session.players || [];
    const matches = session.matches || [];
    totalPlayers += players.length;

    players.forEach((p) => {
      const price = typeof p.price === "number" ? p.price : 0;

      if (isPlayerPaidWithCharge(p.paymentStatus, p.paymentMethod)) {
        totalIncome += price;
      }
      const existing = playerStats.get(p.id) || {
        id: p.id,
        name: p.name,
        matches: 0,
        longestWaitTimeMs: 0,
      };
      const matchesCount = (p.matches ?? existing.matches ?? 0) || 0;
      const longestWaitTimeMs = Math.max(
        existing.longestWaitTimeMs || 0,
        p.longestWaitTimeMs || 0
      );
      playerStats.set(p.id, {
        ...existing,
        name: p.name,
        matches: matchesCount,
        longestWaitTimeMs,
      });
    });

    matches.forEach((m) => allMatches.push(m));
  });

  const allPlayers = Array.from(playerStats.values());
  const totalMatchesPlayed = allPlayers.reduce(
    (sum, p) => sum + (p.matches || 0),
    0
  );
  const avgGamesPerPlayer = allPlayers.length
    ? totalMatchesPlayed / allPlayers.length
    : 0;

  const waits = allPlayers.map((p) => p.longestWaitTimeMs || 0).filter((ms) => ms > 0);
  const maxWaitMs = waits.length ? Math.max(...waits) : 0;
  const avgWaitMs = waits.length
    ? waits.reduce((sum, v) => sum + v, 0) / waits.length
    : 0;

  let maxGames = 0;
  const topPlayersByGames = allPlayers
    .slice()
    .sort((a, b) => (b.matches || 0) - (a.matches || 0))
    .slice(0, 10)
    .map((p) => {
      const m = p.matches || 0;
      if (m > maxGames) maxGames = m;
      return { playerId: p.id, name: p.name, matches: m };
    });

  const openPlayPayments = aggregatePayments(
    sessionsToday.flatMap((session) => session.players || []),
    (player) => ({
      status: player.paymentStatus,
      amount: typeof player.price === "number" ? player.price : 0,
    })
  );
  // Rentals Analytics (V2) — booking-level payment (discount-aware)
  const rentalPaymentsList = [];
  const countedBookingIds = new Set();

  Object.values(slotsV2 || {}).forEach((slot) => {
    if (!slot) return;
    const sYMD = slot.date || toYMD(slot.startTime);
    if (sYMD !== targetYMD) return;
    if (slot.status === "CANCELLED") return;
    pushBookingRentalPayment(bookingsV2, slot.bookingId, slotsV2, rentalPaymentsList, countedBookingIds);
  });

  // Unique Rentals Count (Based on slots active today)
  const uniqueRentalIds = new Set();
  Object.values(slotsV2 || {}).forEach((slot) => {
    const sYMD = slotYMD(slot) || toYMD(slot.startTime);
    if (!slot || sYMD !== targetYMD || slot.status === "CANCELLED") return;
    const booking = bookingsV2[slot.bookingId];
    if (!isRentalBooking(booking)) return;
    uniqueRentalIds.add(slot.bookingId);
  });

  const rentalStats = {
    totalRentals: uniqueRentalIds.size,
    totalIncome: rentalPaymentsList.reduce((sum, item) => item.status === 'paid' ? sum + item.amount : sum, 0),
    byCourt: {} // Utilization calc below
  };

  // Utilization (V2)
  // Sum duration of slots today per court
  Object.values(slotsV2 || {}).forEach(slot => {
    const sYMD = slot.date || toYMD(slot.startTime);
    if (!slot || sYMD !== targetYMD || slot.status === 'CANCELLED') return;
    let hours = 0;
    if (typeof slot.startTime === 'number' && typeof slot.endTime === 'number') {
      hours = Math.max(0, (slot.endTime - slot.startTime) / 60);
    } else {
      const start = new Date(slot.startTime);
      const end = new Date(slot.endTime);
      hours = Math.max(0, (end - start) / (1000 * 60 * 60));
    }
    const courtName = `Court ${slot.courtId}`;
    rentalStats.byCourt[courtName] = (rentalStats.byCourt[courtName] || 0) + hours;
  });

  const rentalPayments = aggregatePayments(rentalPaymentsList, (item) => ({
    status: item.status,
    amount: item.amount,
    paymentMethod: item.paymentMethod
  }));

  // Match history analytics (aggregate across today's sessions)
  const matchesWithDuration = allMatches
    .map((m) => {
      const start = Number(m.startTime || 0);
      const end = Number(m.endTime || 0);
      const durationMs = Number(m.durationMs || (end && start ? Math.max(0, end - start) : 0));
      return { ...m, durationMs };
    })
    .filter((m) => Number(m.durationMs) > 0);

  const totalDuration = matchesWithDuration.reduce((sum, m) => sum + (m.durationMs || 0), 0);
  const avgDurationMs = matchesWithDuration.length ? Math.round(totalDuration / matchesWithDuration.length) : null;
  let shortestMatch = matchesWithDuration.length ? matchesWithDuration[0] : null;
  let longestMatch = matchesWithDuration.length ? matchesWithDuration[0] : null;
  matchesWithDuration.forEach((m) => {
    if (shortestMatch && m.durationMs < shortestMatch.durationMs) shortestMatch = m;
    if (longestMatch && m.durationMs > longestMatch.durationMs) longestMatch = m;
  });
  const courtCounts = {};
  matchesWithDuration.forEach((m) => {
    const key = m.courtName || (m.courtId != null ? `Court ${m.courtId}` : "Unknown court");
    courtCounts[key] = (courtCounts[key] || 0) + 1;
  });
  let mostActiveCourt = null;
  Object.entries(courtCounts).forEach(([courtName, count]) => {
    if (!mostActiveCourt || count > mostActiveCourt.count) {
      mostActiveCourt = { courtName, count };
    }
  });
  const playerCounts = {};
  matchesWithDuration.forEach((m) => {
    const ids = [...(m.teams?.green || []), ...(m.teams?.blue || [])];
    ids.forEach((id) => { playerCounts[id] = (playerCounts[id] || 0) + 1; });
  });
  let topPlayer = null;
  Object.entries(playerCounts).forEach(([id, count]) => {
    // We don't have player names here reliably; fill with ID reference
    if (!topPlayer || count > topPlayer.count) {
      const found = globalPlayers.find(p => String(p.id) === String(id));
      const name = found ? found.name : `P${id}`;
      topPlayer = { id, name, count };
    }
  });

  const playerWinStats = new Map();
  allMatches.forEach(m => {
    if (!m.winner) return;
    const greenIds = m.teams?.green || [];
    const blueIds = m.teams?.blue || [];
    const winner = m.winner;
    const process = (ids, result) => {
      ids.forEach(id => {
        const p = playerWinStats.get(id) || { id: id, wins: 0, total: 0, name: `P${id}` };
        p.total += 1;
        if (result === 'win') p.wins += 1;
        playerWinStats.set(id, p);
      });
    };
    process(greenIds, winner === 'green' ? 'win' : 'loss');
    process(blueIds, winner === 'blue' ? 'win' : 'loss');
  });

  const topPlayersByWinRate = Array.from(playerWinStats.values())
    .map(p => {
      const ref = playerStats.get(p.id?.toString()) || playerStats.get(Number(p.id));
      if (ref && ref.name) {
        p.name = ref.name;
      } else {
        const globalRef = globalPlayers.find(gp => String(gp.id) === String(p.id));
        if (globalRef) p.name = globalRef.name;
      }
      p.percent = p.total > 0 ? (p.wins / p.total) * 100 : 0;
      return p;
    })
    .filter(p => p.total >= 2) // Min 2 matches
    .sort((a, b) => {
      if (b.percent !== a.percent) return b.percent - a.percent;
      return b.wins - a.wins;
    })
    .slice(0, 10);

  const topPlayerByWinRate = topPlayersByWinRate.length > 0 ? topPlayersByWinRate[0] : null;

  const arrivalTimes = [];
  sessionsToday.forEach(s => {
    (s.players || []).forEach(p => {
      const time = p.arrivalTime || p.joinedAt;
      if (time) {
        const d = new Date(time);
        if (Number.isFinite(d.getTime())) {
          arrivalTimes.push(d.getHours() * 60 + d.getMinutes());
        }
      }
    });
  });
  const avgArrivalMin = arrivalTimes.length ? Math.round(arrivalTimes.reduce((a, b) => a + b, 0) / arrivalTimes.length) : null;
  const avgArrivalTime = avgArrivalMin !== null ? `${Math.floor(avgArrivalMin / 60).toString().padStart(2, '0')}:${(avgArrivalMin % 60).toString().padStart(2, '0')}` : "N/A";

  const slotsToday = Object.values(slotsV2 || {}).filter((slot) => {
    if (!slot || slot.status === "CANCELLED") return false;
    const sYMD = slot.date || toYMD(slot.startTime);
    return sYMD === targetYMD;
  });
  rentalStats.byClient = buildRentalClientStats(bookingsV2, slotsToday, slotsV2);
  const paymentDetails = collectPaymentDetails(sessionsToday, bookingsV2, slotsToday, slotsV2);

  return {
    date: targetYMD,
    rentals: rentalStats,
    openPlay: {
      totalPlayers,
      totalIncome,
    },
    games: {
      avgWaitMs,
      maxWaitMs,
      avgGamesPerPlayer,
      maxGamesPerPlayer: maxGames,
      topPlayersByGames,
      topPlayerByWinRate,
      avgArrivalTime,
      summary: { avgDurationMs, shortestMatch, longestMatch, mostActiveCourt, topPlayer },
    },
    payments: {
      openPlay: openPlayPayments,
      rentals: rentalPayments,
    },
    paymentDetails,
  };
};

// Compute daily metrics (income, players) for the last N days ending at `today` (inclusive).
// Returns an array of { date: 'YYYY-MM-DD', openPlayIncome, rentalIncome, total, visitorCount } sorted ascending by date.
export const computeDailyMetricsLastNDays = (
  opSessions = [],
  bookingsV2 = {},
  slotsV2 = {},
  N = 7,
  today = new Date()
) => {
  const days = Math.max(1, Number(N) || 7);
  const base = new Date(today);
  const start = new Date(base.getFullYear(), base.getMonth(), base.getDate() - (days - 1), 0, 0, 0, 0);

  const result = [];
  for (let i = 0; i < days; i++) {
    const d = new Date(start.getFullYear(), start.getMonth(), start.getDate() + i, 0, 0, 0, 0);
    const ymd = toYMDLocal(d);

    // Open Play stats per day
    const sessionsOnDay = (opSessions || []).filter((s) => {
      if (!isReportableOpSession(s)) return false;
      return toYMD(s.startedAt || s.endedAt || 0) === ymd;
    });

    let dailyVisitors = 0;
    const openPlayIncome = sessionsOnDay.reduce((sum, s) => {
      const players = s.players || [];
      dailyVisitors += players.length;
      const inc = players.reduce((pSum, p) => {
        const price = typeof p.price === "number" ? p.price : 0;
        return isPlayerPaidWithCharge(p.paymentStatus, p.paymentMethod) ? pSum + price : pSum;
      }, 0);
      return sum + inc;
    }, 0);

    let dailyRentalIncome = 0;
    const uniqueRentalsOnDay = new Set();
    const bookingsOnDay = new Set();

    Object.values(slotsV2 || {}).forEach((slot) => {
      if (!slot) return;
      const sYMD = slotYMD(slot) || toYMD(slot.startTime);
      if (sYMD !== ymd) return;
      if (slot.status === "CANCELLED") return;
      const booking = bookingsV2[slot.bookingId];
      if (isRentalBooking(booking)) {
        uniqueRentalsOnDay.add(slot.bookingId);
        bookingsOnDay.add(slot.bookingId);
      }
    });

    bookingsOnDay.forEach((bookingId) => {
      dailyRentalIncome += bookingRentalIncome(bookingsV2, bookingId, slotsV2, ymd);
    });

    result.push({
      date: ymd,
      openPlayIncome,
      rentalIncome: dailyRentalIncome,
      total: openPlayIncome + dailyRentalIncome,
      visitorCount: dailyVisitors,
      rentalCount: uniqueRentalsOnDay.size
    });
  }

  return result;
};

// Compute daily metrics for an arbitrary date range (start -> end inclusive)
export const computeDailyMetricsInRange = (
  opSessions = [],
  bookingsV2 = {},
  slotsV2 = {},
  startDateStr,
  endDateStr
) => {
  const start = parseYMDLocal(startDateStr);
  const end = parseYMDLocal(endDateStr);
  const result = [];

  if (!start || !end || start > end) return [];

  for (let d = new Date(start); d <= end; d.setDate(d.getDate() + 1)) {
    const ymd = toYMDLocal(d);

    // Open Play calculations
    const sessionsOnDay = (opSessions || []).filter((s) => {
      if (!isReportableOpSession(s)) return false;
      return toYMD(s.startedAt || s.endedAt || "") === ymd;
    });

    let dailyVisitors = 0;
    const openPlayIncome = sessionsOnDay.reduce((sum, s) => {
      const players = s.players || [];
      dailyVisitors += players.length;
      const inc = players.reduce((pSum, p) => {
        const price = typeof p.price === "number" ? p.price : 0;
        return isPlayerPaidWithCharge(p.paymentStatus, p.paymentMethod) ? pSum + price : pSum;
      }, 0);
      return sum + inc;
    }, 0);

    let dailyRentalIncome = 0;
    const uniqueRentalsOnDay = new Set();
    const countedDayBookings = new Set();
    Object.values(slotsV2 || {}).forEach((slot) => {
      if (!slot) return;
      const sYMD = slotYMD(slot) || toYMD(slot.startTime);
      if (sYMD !== ymd) return;
      if (slot.status === "CANCELLED") return;
      const booking = bookingsV2[slot.bookingId];
      if (isRentalBooking(booking)) {
        uniqueRentalsOnDay.add(slot.bookingId);
      }
      if (!countedDayBookings.has(slot.bookingId)) {
        countedDayBookings.add(slot.bookingId);
        dailyRentalIncome += bookingRentalIncome(bookingsV2, slot.bookingId, slotsV2, ymd);
      }
    });

    result.push({
      date: ymd,
      openPlayIncome,
      rentalIncome: dailyRentalIncome,
      total: openPlayIncome + dailyRentalIncome,
      visitorCount: dailyVisitors,
      rentalCount: uniqueRentalsOnDay.size
    });
  }

  return result;
};

// Compute income for the last N days ending at `today` (inclusive).
// Returns an array of { date: 'YYYY-MM-DD', openPlayIncome, rentalIncome, total } sorted ascending by date.


// Build a range-aware report for dashboard tiles.
// range: 'day' | 'week' | 'month'
// today: Date
// Returns shape compatible with dashboard usage:
// {
//   label, date,
//   openPlay: { totalPlayers, totalIncome },
//   rentals: { totalRentals, totalIncome },
//   games: { avgWaitMs, maxWaitMs, avgGamesPerPlayer, maxGamesPerPlayer, topPlayersByGames },
//   payments: { openPlay: buckets, rentals: buckets },
//   incomeSeries?: [{date, openPlayIncome, rentalIncome, total}]
// }
export const buildRangeReport = (
  range = "day",
  today = new Date(),
  opSessions = [],
  bookingsV2 = {},
  slotsV2 = {},
  settings = {},
  globalPlayers = []
) => {
  const label = range === "day" ? "Today" : range === "week" ? "This Week" : "This Month";

  let startDate, endDate;
  const t = new Date(today);

  if (range === "day") {
    const daily = buildDailyReport(opSessions, bookingsV2, slotsV2, today, globalPlayers);
    return { label, ...daily, dailyMetrics: [] };
  } else if (range === "week") {
    // This Week (Sunday to Saturday)
    const day = t.getDay(); // 0 (Sun) - 6 (Sat)
    const diff = t.getDate() - day; // adjust when day is sunday
    startDate = new Date(t.setDate(diff));
    endDate = new Date(t.setDate(startDate.getDate() + 6));
  } else {
    // This Month (1st to Last Day)
    startDate = new Date(t.getFullYear(), t.getMonth(), 1);
    endDate = new Date(t.getFullYear(), t.getMonth() + 1, 0);
  }

  // Ensure robust local YMD strings
  const sStr = startDate.toLocaleDateString('en-CA');
  const eStr = endDate.toLocaleDateString('en-CA');

  // Use Range Compute
  const series = computeDailyMetricsInRange(opSessions, bookingsV2, slotsV2, sStr, eStr);
  const dateRangeSet = new Set(series.map((d) => d.date));

  const sessionsInRange = (opSessions || []).filter((s) => {
    if (!isReportableOpSession(s)) return false;
    const ymd = toYMD(s.startedAt || s.endedAt || 0);
    return dateRangeSet.has(ymd);
  });
  // Filter Bookings/Slots in range for aggregate (V2)
  // For V2, we care about SLOTS in range for income/usage, and BOOKINGS for count?
  // Daily logic iterates days. Here we need totals across range.

  // Actually, for aggregate totals, it's safer to just sum up the 'series' result we just computed?
  // The series has daily income. Summing it gives range total income.
  // Visitor count sum gives total visitors (unique per day).

  // BUT we also need breakdown by Payment Method, Game Stats etc. which Series doesn't have.
  // So we do need to iterate raw data within range.

  const slotsInRange = [];
  const bookingsIdsInRange = new Set();

  Object.values(slotsV2 || {}).forEach((slot) => {
    if (!slot) return;
    const ymd = slotYMD(slot) || toYMD(slot.startTime);
    if (slot.status !== "CANCELLED" && dateRangeSet.has(ymd)) {
      slotsInRange.push(slot);
      if (isRentalBooking(bookingsV2[slot.bookingId])) {
        bookingsIdsInRange.add(slot.bookingId);
      }
    }
  });

  // Open Play Totals
  let totalPlayers = 0;
  let totalOpIncome = 0;
  const playerStats = new Map();
  sessionsInRange.forEach((session) => {
    const players = session.players || [];
    totalPlayers += players.length;
    players.forEach((p) => {
      const price = typeof p.price === "number" ? p.price : 0;
      if (isPlayerPaidWithCharge(p.paymentStatus, p.paymentMethod)) {
        totalOpIncome += price;
      }
      const existing = playerStats.get(p.id) || { id: p.id, name: p.name, matches: 0, longestWaitTimeMs: 0 };
      const matchesCount = (p.matches ?? existing.matches ?? 0) || 0;
      const longestWaitTimeMs = Math.max(existing.longestWaitTimeMs || 0, p.longestWaitTimeMs || 0);
      playerStats.set(p.id, { ...existing, name: p.name, matches: matchesCount, longestWaitTimeMs });
    });
  });

  // Game Stats Calculation ... (Omitting full rewrite, assume identical logic preserved above)
  const allPlayers = Array.from(playerStats.values());
  const totalMatchesPlayed = allPlayers.reduce((sum, p) => sum + (p.matches || 0), 0);
  const avgGamesPerPlayer = allPlayers.length ? totalMatchesPlayed / allPlayers.length : 0;
  const waits = allPlayers.map((p) => p.longestWaitTimeMs || 0).filter((ms) => ms > 0);
  const maxWaitMs = waits.length ? Math.max(...waits) : 0;
  const avgWaitMs = waits.length ? waits.reduce((sum, v) => sum + v, 0) / waits.length : 0;

  let maxGames = 0;
  const topPlayersByGames = allPlayers
    .slice()
    .sort((a, b) => (b.matches || 0) - (a.matches || 0))
    .slice(0, 10)
    .map((p) => {
      const m = p.matches || 0;
      if (m > maxGames) maxGames = m;
      return { playerId: p.id, name: p.name, matches: m };
    });

  // Gameplay Stats
  const allMatchesInRange = [];
  sessionsInRange.forEach(s => {
    if (s.matches) allMatchesInRange.push(...s.matches);
  });

  const playerWinStats = new Map();
  allMatchesInRange.forEach(m => {
    if (!m.winner) return;
    const greenIds = m.teams?.green || [];
    const blueIds = m.teams?.blue || [];
    const winner = m.winner;
    const process = (ids, result) => {
      ids.forEach(id => {
        const p = playerWinStats.get(id) || { id: id, wins: 0, total: 0, name: `P${id}` };
        p.total += 1;
        if (result === 'win') p.wins += 1;
        playerWinStats.set(id, p);
      });
    };
    process(greenIds, winner === 'green' ? 'win' : 'loss');
    process(blueIds, winner === 'blue' ? 'win' : 'loss');
  });

  const topPlayersByWinRate = Array.from(playerWinStats.values())
    .map(p => {
      const ref = playerStats.get(p.id?.toString()) || playerStats.get(Number(p.id));
      if (ref && ref.name) {
        p.name = ref.name;
      } else {
        const globalRef = globalPlayers.find(gp => String(gp.id) === String(p.id));
        if (globalRef) p.name = globalRef.name;
      }
      p.percent = p.total > 0 ? (p.wins / p.total) * 100 : 0;
      return p;
    })
    .filter(p => p.total >= 2) // Min 2 matches
    .sort((a, b) => {
      if (b.percent !== a.percent) return b.percent - a.percent;
      return b.wins - a.wins; // Tie-break with more wins
    })
    .slice(0, 10);

  const topPlayerByWinRate = topPlayersByWinRate.length > 0 ? topPlayersByWinRate[0] : null;

  const arrivalTimes = [];
  sessionsInRange.forEach(s => {
    (s.players || []).forEach(p => {
      const time = p.arrivalTime || p.joinedAt;
      if (time) {
        const d = new Date(time);
        if (Number.isFinite(d.getTime())) {
          arrivalTimes.push(d.getHours() * 60 + d.getMinutes());
        }
      }
    });
  });
  const avgArrivalMin = arrivalTimes.length ? Math.round(arrivalTimes.reduce((a, b) => a + b, 0) / arrivalTimes.length) : null;
  const avgArrivalTime = avgArrivalMin !== null ? `${Math.floor(avgArrivalMin / 60).toString().padStart(2, '0')}:${(avgArrivalMin % 60).toString().padStart(2, '0')}` : "N/A";

  // Rentals Logic (V2 Aggregate in Range)
  const rentalHoursByCourt = {};
  slotsInRange.forEach(slot => {
    let hours = 0;
    if (typeof slot.startTime === 'number' && typeof slot.endTime === 'number') {
      hours = Math.max(0, (slot.endTime - slot.startTime) / 60);
    } else {
      const start = new Date(slot.startTime);
      const end = new Date(slot.endTime);
      hours = Math.max(0, (end - start) / (1000 * 60 * 60));
    }
    const name = `Court ${slot.courtId}`;
    rentalHoursByCourt[name] = (rentalHoursByCourt[name] || 0) + hours;
  });

  const rentalPaymentsList = [];
  const countedRangeBookings = new Set();
  slotsInRange.forEach((slot) => {
    pushBookingRentalPayment(bookingsV2, slot.bookingId, slotsV2, rentalPaymentsList, countedRangeBookings);
  });
  const rentalIncomeTotal = rentalPaymentsList.reduce(
    (sum, item) => (item.status === "paid" ? sum + item.amount : sum),
    0
  );

  // Reconstruct an "Items" list for the Modal (List of bookings involved)
  // We can pass the full booking objects for the modal list
  const rentalsItems = Array.from(bookingsIdsInRange).map(id => bookingsV2[id]).filter(Boolean);

  const rentalsTotals = {
    totalRentals: bookingsIdsInRange.size,
    totalIncome: rentalIncomeTotal,
    items: rentalsItems, // For legacy compatibility in modal, might need adapter
    byClient: buildRentalClientStats(bookingsV2, slotsInRange, slotsV2),
  };

  const payments = {
    openPlay: aggregatePayments(sessionsInRange.flatMap((s) => s.players || []), (p) => ({ status: p.paymentStatus, amount: typeof p.price === 'number' ? p.price : 0, paymentMethod: p.paymentMethod })),
    rentals: aggregatePayments(rentalPaymentsList, (item) => ({ status: item.status, amount: item.amount, paymentMethod: item.paymentMethod })),
  };

  const paymentDetails = collectPaymentDetails(sessionsInRange, bookingsV2, slotsInRange, slotsV2);

  return {
    label,
    date: toYMD(today),
    openPlay: { totalPlayers, totalIncome: totalOpIncome },
    rentals: { ...rentalsTotals, byCourt: rentalHoursByCourt },
    games: { avgWaitMs, maxWaitMs, avgGamesPerPlayer, maxGamesPerPlayer: maxGames, topPlayersByGames, topPlayersByWinRate, topPlayerByWinRate, avgArrivalTime },
    payments,
    paymentDetails,
    dailyMetrics: series,
  };
};

// Compute utilization (booked vs. free hours) for the last N days
// Returns array of { date, bookedHours, freeHours, totalHours }
export const computeUtilizationForLastNDays = (
  bookingsV2 = {},
  slotsV2 = {},
  calendarCourtsCount = 0,
  settings = {},
  N = 7,
  today = new Date()
) => {
  const days = Math.max(1, Number(N) || 7);
  const base = new Date(today);
  const start = new Date(base.getFullYear(), base.getMonth(), base.getDate() - (days - 1), 0, 0, 0, 0);
  const openHour = Number(settings?.calendarOpenHour ?? DEFAULT_CALENDAR_OPEN_HOUR);
  const closeHour = Number(settings?.calendarCloseHour ?? DEFAULT_CALENDAR_CLOSE_HOUR);
  const hoursPerDay = Math.max(0, closeHour - openHour);
  const totalHoursPerDay = Math.max(0, hoursPerDay * Math.max(1, Number(calendarCourtsCount) || 0));

  const result = [];
  for (let i = 0; i < days; i++) {
    const d = new Date(start.getFullYear(), start.getMonth(), start.getDate() + i, 0, 0, 0, 0);
    const ymd = toYMDLocal(d);

    let bookedHours = 0;
    Object.values(slotsV2 || {}).forEach((slot) => {
      if (!slot || slot.status === "CANCELLED") return;
      const sYMD = slotYMD(slot);
      if (!sYMD || sYMD !== ymd) return;
      bookedHours += slotCourtHours(slot);
    });

    const freeHours = Math.max(0, totalHoursPerDay - bookedHours);
    result.push({ date: ymd, bookedHours, freeHours, totalHours: totalHoursPerDay });
  }
  return result;
};

/** Range YMD bounds for day | week | month (Sun–Sat week). */
export const getRangeYMDBounds = (range = "day", today = new Date()) => {
  const t = new Date(today);
  if (range === "day") {
    const ymd = toYMDLocal(t);
    return { startYmd: ymd, endYmd: ymd };
  }
  if (range === "week") {
    const day = t.getDay();
    const start = new Date(t.getFullYear(), t.getMonth(), t.getDate() - day, 0, 0, 0, 0);
    const end = new Date(start.getFullYear(), start.getMonth(), start.getDate() + 6, 0, 0, 0, 0);
    return { startYmd: toYMDLocal(start), endYmd: toYMDLocal(end) };
  }
  const start = new Date(t.getFullYear(), t.getMonth(), 1, 0, 0, 0, 0);
  const end = new Date(t.getFullYear(), t.getMonth() + 1, 0, 0, 0, 0, 0);
  return { startYmd: toYMDLocal(start), endYmd: toYMDLocal(end) };
};

/** Occupancy hours for a YMD range: rented, blocked (OP), free. */
export const computeOccupancyBreakdownForRange = (
  bookingsV2 = {},
  slotsV2 = {},
  startYmd,
  endYmd,
  calendarCourtsCount = 0,
  settings = {}
) => {
  const openHour = Number(settings?.calendarOpenHour ?? DEFAULT_CALENDAR_OPEN_HOUR);
  const closeHour = Number(settings?.calendarCloseHour ?? DEFAULT_CALENDAR_CLOSE_HOUR);
  const hoursPerDay = Math.max(0, closeHour - openHour);
  const dayCount = daysBetweenYMD(startYmd, endYmd);
  const totalHours = Math.max(0, hoursPerDay * Math.max(1, Number(calendarCourtsCount) || 0) * dayCount);

  let rentedHours = 0;
  let blockedHours = 0;

  Object.values(slotsV2 || {}).forEach((slot) => {
    if (!slot || slot.status === "CANCELLED") return;
    const ymd = slotYMD(slot);
    if (!ymd || ymd < startYmd || ymd > endYmd) return;
    const hours = slotCourtHours(slot);
    const booking = bookingsV2[slot.bookingId];
    if (isOpenPlayCalendarBlock(booking)) blockedHours += hours;
    else if (isRentalBooking(booking)) rentedHours += hours;
  });

  const freeHours = Math.max(0, totalHours - rentedHours - blockedHours);
  return { rentedHours, blockedHours, freeHours, totalHours };
};

const sumBreakdownTotals = (rows) =>
  rows.reduce(
    (acc, row) => {
      if (!row) return acc;
      acc.courtGross += row.courtGross || 0;
      acc.pickleCamPesos += row.pickleCamPesos || 0;
      acc.ballsPesos += row.ballsPesos || 0;
      acc.discountGiven += row.discountGiven || 0;
      acc.grossBeforeDiscount += row.grossBeforeDiscount || 0;
      acc.computedNet += row.computedNet || 0;
      acc.adjustment += row.adjustment || 0;
      acc.netDue += row.netDue || 0;
      acc.amountPaid += row.amountPaid || 0;
      acc.balance += row.balance || 0;
      if (row.hasPickleCam) acc.pickleCamBookingCount += 1;
      acc.ballUnitsSold += row.ballUnits || 0;
      acc.bookingCount += 1;
      return acc;
    },
    {
      courtGross: 0,
      pickleCamPesos: 0,
      ballsPesos: 0,
      discountGiven: 0,
      grossBeforeDiscount: 0,
      computedNet: 0,
      adjustment: 0,
      netDue: 0,
      amountPaid: 0,
      balance: 0,
      bookingCount: 0,
      pickleCamBookingCount: 0,
      ballUnitsSold: 0,
    }
  );

/** Rental income breakdown for bookings whose earliest slot falls in range. */
export const buildRentalIncomeBreakdownForRange = (
  bookingsV2 = {},
  slotsV2 = {},
  startYmd,
  endYmd,
  settings = {}
) => {
  const seen = new Set();
  const bookings = [];

  Object.values(bookingsV2 || {}).forEach((booking) => {
    if (!isRentalBooking(booking)) return;
    const earliest = getEarliestSlotYMD(booking.id, slotsV2);
    if (!earliest || earliest < startYmd || earliest > endYmd) return;
    if (seen.has(booking.id)) return;
    seen.add(booking.id);
    const row = buildRentalBookingIncomeBreakdown(booking, slotsV2, settings);
    if (row) bookings.push(row);
  });

  return { bookings, totals: sumBreakdownTotals(bookings) };
};

/** Court gross ₱ by court for rental slots in date range. */
export const buildCourtGrossByCourtInRange = (bookingsV2 = {}, slotsV2 = {}, startYmd, endYmd) => {
  const byCourt = {};
  Object.values(slotsV2 || {}).forEach((slot) => {
    if (!slot || slot.status === "CANCELLED") return;
    const ymd = slotYMD(slot);
    if (!ymd || ymd < startYmd || ymd > endYmd) return;
    const booking = bookingsV2[slot.bookingId];
    if (!isRentalBooking(booking)) return;
    const cid = slot.courtId;
    const name = `Court ${cid}`;
    if (!byCourt[cid]) byCourt[cid] = { name, revenue: 0, hours: 0 };
    byCourt[cid].revenue += Number(slot.price) || 0;
    byCourt[cid].hours += slotCourtHours(slot);
  });
  return Object.values(byCourt).sort((a, b) => a.name.localeCompare(b.name));
};

/**
 * Top teams for the current session from matches carrying teamMeta.
 * @param {string} rankingMode - "winsFirst" | "winRateFirst"
 */
export const computeTopTeams = (matches = [], sessionStartedAt = 0, rankingMode = "winsFirst") => {
  if (!sessionStartedAt) return [];
  const list = (matches || []).filter(
    (m) =>
      m &&
      m.status === "completed" &&
      m.teamMeta?.sideA?.teamId &&
      m.teamMeta?.sideB?.teamId &&
      (m.endTime || m.startTime || 0) >= sessionStartedAt
  );
  if (!list.length) return [];

  const byTeam = new Map();

  const bump = (teamId, playedInc, winInc, playerIds = []) => {
    const id = String(teamId);
    if (!byTeam.has(id)) {
      byTeam.set(id, { wins: 0, matchesPlayed: 0, playerIds: new Set() });
    }
    const row = byTeam.get(id);
    row.matchesPlayed += playedInc;
    row.wins += winInc;
    playerIds.forEach((pid) => row.playerIds.add(String(pid)));
  };

  list.forEach((m) => {
    const { sideA, sideB } = m.teamMeta;
    const w = m.winner;
    const aWon = w === "green";
    const bWon = w === "blue";
    const tie = w === "tie" || w == null;
    bump(sideA.teamId, 1, tie ? 0 : aWon ? 1 : 0, sideA.players || []);
    bump(sideB.teamId, 1, tie ? 0 : bWon ? 1 : 0, sideB.players || []);
  });

  const rows = [...byTeam.entries()].map(([teamId, v]) => {
    const winPct = v.matchesPlayed > 0 ? v.wins / v.matchesPlayed : 0;
    return {
      teamId,
      wins: v.wins,
      matchesPlayed: v.matchesPlayed,
      winPct,
      playerCount: v.playerIds.size,
    };
  });

  const cmp = (a, b) => {
    if (rankingMode === "winRateFirst") {
      if (b.winPct !== a.winPct) return b.winPct - a.winPct;
      if (b.wins !== a.wins) return b.wins - a.wins;
      return b.playerCount - a.playerCount;
    }
    if (b.wins !== a.wins) return b.wins - a.wins;
    if (b.winPct !== a.winPct) return b.winPct - a.winPct;
    return b.playerCount - a.playerCount;
  };

  rows.sort(cmp);
  return rows;
};
