/**
 * Pure club-entity ops. IndexedDB is the source of truth; React state is a cache.
 * Each staff action is one op: conflict checks, then all writes, or nothing.
 * A rev mismatch rebases when the changed fields do not overlap (payment vs end-game
 * status). Overlapping fields abort the whole op.
 */

export const CONFLICT_TOAST = "Court changed in another window — showing the latest";
export const QUEUE_CONFLICT_TOAST = "Queue changed in another window — showing the latest";
export const SESSION_CONFLICT_TOAST = "Session changed in another window — showing the latest";
export const PLAYER_CONFLICT_TOAST = "Player changed in another window — showing the latest";
export const MATCH_CONFLICT_TOAST = "Match changed in another window — showing the latest";
export const SETTINGS_CONFLICT_TOAST = "Settings changed in another window — showing the latest";
export const HOLD_CONFLICT_TOAST = "Hold changed in another window — showing the latest";
export const GENERIC_CONFLICT_TOAST = "That change conflicted in another window — showing the latest";

export const SYNC_CHANNEL = "dink_manager_v2";
export const SYNC_PING_KEY = "sdSyncPing";
export const APPLIED_OP_CAP = 200;

const CONFLICT_BY_KIND = {
  court: CONFLICT_TOAST,
  queueItem: QUEUE_CONFLICT_TOAST,
  session: SESSION_CONFLICT_TOAST,
  bundle: SESSION_CONFLICT_TOAST,
  player: PLAYER_CONFLICT_TOAST,
  match: MATCH_CONFLICT_TOAST,
  settings: SETTINGS_CONFLICT_TOAST,
  hold: HOLD_CONFLICT_TOAST,
};

/** Toast copy for a failed op. Queue and session beat a court key when both conflict. */
export function conflictToast(conflicts) {
  const list = Array.isArray(conflicts) ? conflicts : [];
  if (list.length === 0) return GENERIC_CONFLICT_TOAST;
  const kinds = [];
  list.forEach((conflict) => {
    const kind = String(conflict?.key || "").split(":")[0];
    if (kind && !kinds.includes(kind)) kinds.push(kind);
  });
  if (!kinds.length) return GENERIC_CONFLICT_TOAST;
  if (kinds.includes("queueItem")) return QUEUE_CONFLICT_TOAST;
  if (kinds.includes("session") || kinds.includes("bundle")) return SESSION_CONFLICT_TOAST;
  if (kinds.includes("court")) return CONFLICT_TOAST;
  if (kinds.includes("player")) return PLAYER_CONFLICT_TOAST;
  if (kinds.includes("match")) return MATCH_CONFLICT_TOAST;
  if (kinds.includes("settings")) return SETTINGS_CONFLICT_TOAST;
  if (kinds.includes("hold")) return HOLD_CONFLICT_TOAST;
  const known = kinds.find((kind) => CONFLICT_BY_KIND[kind]);
  return (known && CONFLICT_BY_KIND[known]) || GENERIC_CONFLICT_TOAST;
}

export function saveFailureToast(op) {
  const writes = op?.writes || [];
  const tombs = op?.tombstones || [];
  const endsCourt = writes.some((write) => (
    write.kind === "court"
    && Array.isArray(write.base?.players)
    && write.base.players.length > 0
    && Array.isArray(write.next?.players)
    && write.next.players.length === 0
  ));
  if (tombs.some((tomb) => tomb.kind === "queueItem") && writes.some((write) => write.kind === "court")) {
    return "Could not send that match. Showing the last saved queue.";
  }
  if (writes.some((write) => write.kind === "queueItem" && (write.base == null || write.baseRev === 0))) {
    return "Could not generate that match. Showing the last saved queue.";
  }
  if (endsCourt) return "Could not end that game. Showing the last saved court.";
  return "Could not save that change. Showing the last saved game.";
}

export function encodeSyncPing(message) {
  return JSON.stringify({
    opId: message?.opId || "ping",
    t: Date.now(),
    keys: Array.isArray(message?.keys) ? message.keys : [],
  });
}

/** `keys: null` is a legacy ping that did not name records. */
export function decodeSyncPing(value) {
  const raw = String(value || "");
  if (raw.startsWith("{")) {
    try {
      const parsed = JSON.parse(raw);
      return {
        opId: parsed?.opId || "ping",
        keys: Array.isArray(parsed?.keys) ? parsed.keys : [],
      };
    } catch (err) {
      return { opId: "ping", keys: [] };
    }
  }
  return { opId: raw.split(":")[0] || "ping", keys: null };
}

const META_FIELDS = new Set(["rev", "updatedAt", "actorId", "key", "kind", "deleted", "deletedAt"]);

export function entityKey(kind, id) {
  return `${kind}:${id}`;
}

export function deepEqual(a, b) {
  if (a === b) return true;
  if (typeof a !== typeof b) return false;
  if (a == null || b == null) return a === b;
  if (typeof a !== "object") return false;
  if (Array.isArray(a) || Array.isArray(b)) {
    if (!Array.isArray(a) || !Array.isArray(b) || a.length !== b.length) return false;
    for (let i = 0; i < a.length; i += 1) {
      if (!deepEqual(a[i], b[i])) return false;
    }
    return true;
  }
  const aKeys = Object.keys(a);
  const bKeys = Object.keys(b);
  if (aKeys.length !== bKeys.length) return false;
  for (let i = 0; i < aKeys.length; i += 1) {
    const key = aKeys[i];
    if (!Object.prototype.hasOwnProperty.call(b, key)) return false;
    if (!deepEqual(a[key], b[key])) return false;
  }
  return true;
}

export function changedKeys(base, next) {
  const left = base && typeof base === "object" ? base : {};
  const right = next && typeof next === "object" ? next : {};
  const keys = new Set([...Object.keys(left), ...Object.keys(right)]);
  const out = [];
  keys.forEach((key) => {
    if (META_FIELDS.has(key)) return;
    if (!deepEqual(left[key], right[key])) out.push(key);
  });
  return out;
}

export function shouldApplyRev(cachedRev, incomingRev) {
  const incoming = Number(incomingRev);
  if (!Number.isFinite(incoming)) return false;
  const cached = Number(cachedRev);
  if (!Number.isFinite(cached)) return true;
  return incoming > cached;
}

function cloneData(value) {
  if (value == null || typeof value !== "object") return value;
  if (Array.isArray(value)) return value.map((item) => cloneData(item));
  const out = {};
  Object.keys(value).forEach((key) => {
    if (META_FIELDS.has(key)) return;
    out[key] = cloneData(value[key]);
  });
  return out;
}

/**
 * When stored moved, keep our field edits if they touch different keys.
 * Same key with the same resulting value is not a conflict.
 */
function unionIdList(left, right) {
  const out = [];
  const seen = new Set();
  [...(Array.isArray(left) ? left : []), ...(Array.isArray(right) ? right : [])].forEach((id) => {
    const key = String(id);
    if (seen.has(key)) return;
    seen.add(key);
    out.push(id);
  });
  return out;
}

function unionReleasedByMatch(stored, next) {
  const left = stored && typeof stored === "object" ? stored : {};
  const right = next && typeof next === "object" ? next : {};
  const keys = new Set([...Object.keys(left), ...Object.keys(right)]);
  const out = {};
  keys.forEach((key) => {
    const list = unionIdList(left[key], right[key]);
    if (list.length) out[key] = list;
  });
  return out;
}

const STAT_FIELDS = new Set([
  "pointDifferential",
  "matches",
  "totalMatchTimeMs",
  "averageMatchDurationMs",
]);
const RENTAL_FIELDS = new Set(["locked", "lockReason", "lockedUntil"]);
const STATUS_FIELDS = ["status", "statusUpdatedAt", "waitStart", "departureTime", "savedWaitStart"];
const QUEUE_PLAYER_CAP = 4;

function isIncidentalField(key) {
  return STAT_FIELDS.has(key) || RENTAL_FIELDS.has(key);
}

function isPrimitiveIdList(value) {
  return Array.isArray(value) && value.every((item) => item == null || typeof item === "string" || typeof item === "number");
}

function endsGame(base, next) {
  const before = Array.isArray(base?.players) ? base.players.length : 0;
  const after = Array.isArray(next?.players) ? next.players.length : 0;
  return before > 0 && after === 0;
}

/** Keep stored order, apply removals from either side, then append ids only one side added. */
export function mergeOrderedIds(baseList, storedList, nextList) {
  const base = (Array.isArray(baseList) ? baseList : []).map(String);
  const stored = Array.isArray(storedList) ? storedList : [];
  const next = Array.isArray(nextList) ? nextList : [];
  const baseSet = new Set(base);
  const storedSet = new Set(stored.map(String));
  const nextSet = new Set(next.map(String));
  const removed = new Set(base.filter((id) => !storedSet.has(id) || !nextSet.has(id)));
  const out = [];
  const seen = new Set();
  const push = (id) => {
    const key = String(id);
    if (removed.has(key) || seen.has(key)) return;
    seen.add(key);
    out.push(id);
  };
  stored.forEach(push);
  next.forEach((id) => {
    if (!baseSet.has(String(id))) push(id);
  });
  return out;
}

function queueMembership(list) {
  return Array.isArray(list) ? list : [];
}

function statusStamp(row) {
  const stamp = Number(row?.statusUpdatedAt);
  return Number.isFinite(stamp) ? stamp : 0;
}

/**
 * When stored moved, keep our field edits if they touch different keys.
 * Recent-hold releases union per player instead of conflicting on the whole map.
 * Same key with the same resulting value is not a conflict.
 * Stat fields and rental locks never overlap a user edit.
 * Queue playerIds and order bundles union. Player status follows the later stamp.
 * Ending a game is not blocked by a court timer tick.
 */
export function rebaseRecord(storedData, base, next) {
  const changed = changedKeys(base, next);
  if (changed.length === 0) return { ok: true, data: cloneData(storedData), noop: true };
  const drifted = changedKeys(base, storedData);
  const releaseChanged = changed.includes("releasedByMatch");
  const releaseDrifted = drifted.includes("releasedByMatch");
  const playerIdsChanged = changed.includes("playerIds");
  const playerIdsDrifted = drifted.includes("playerIds");
  const idsChanged = changed.includes("ids") && isPrimitiveIdList(next?.ids);
  const idsDrifted = drifted.includes("ids") && isPrimitiveIdList(storedData?.ids);
  const statusChanged = changed.includes("status");
  const statusDrifted = drifted.includes("status") && !deepEqual(storedData?.status, next?.status);
  let statusWinner = null;
  if (statusChanged && statusDrifted) {
    const storedTs = statusStamp(storedData);
    const nextTs = statusStamp(next);
    if (storedTs === 0 && nextTs === 0) {
      return { ok: false, overlap: ["status"] };
    }
    statusWinner = nextTs >= storedTs ? "next" : "stored";
  }
  const overlap = changed.filter((key) => {
    if (!drifted.includes(key)) return false;
    if (deepEqual(storedData?.[key], next?.[key])) return false;
    if (key === "releasedByMatch" || key === "playerIds") return false;
    if (key === "ids" && idsChanged && idsDrifted) return false;
    if (isIncidentalField(key)) return false;
    if (STATUS_FIELDS.includes(key)) return false;
    if (key === "timer" && endsGame(base, next)) return false;
    return true;
  });
  if (overlap.length > 0) return { ok: false, overlap };
  const merged = cloneData(storedData);
  const skip = new Set(["releasedByMatch", "playerIds"]);
  if (idsChanged && idsDrifted) skip.add("ids");
  if (statusWinner === "stored") STATUS_FIELDS.forEach((key) => skip.add(key));
  changed.forEach((key) => {
    if (skip.has(key)) return;
    merged[key] = cloneData(next[key]);
  });
  if (releaseChanged) {
    merged.releasedByMatch = releaseDrifted
      ? unionReleasedByMatch(storedData?.releasedByMatch, next?.releasedByMatch)
      : cloneData(next?.releasedByMatch || {});
  }
  if (playerIdsChanged) {
    const mergedIds = playerIdsDrifted
      ? mergeOrderedIds(base?.playerIds, storedData?.playerIds, next?.playerIds)
      : queueMembership(next?.playerIds);
    if (mergedIds.length > QUEUE_PLAYER_CAP) return { ok: false, overlap: ["playerIds"] };
    merged.playerIds = cloneData(mergedIds);
  }
  if (idsChanged && idsDrifted) {
    merged.ids = mergeOrderedIds(base?.ids, storedData?.ids, next?.ids);
  }
  if (endsGame(base, next) && next && Object.prototype.hasOwnProperty.call(next, "timer")) {
    merged.timer = cloneData(next.timer);
  }
  return {
    ok: true,
    data: merged,
    statusTouch: statusChanged,
    rebased: drifted.some((key) => key !== "releasedByMatch") || (releaseChanged && releaseDrifted) || playerIdsDrifted || idsDrifted || statusWinner === "stored",
  };
}

function asMap(records) {
  if (records instanceof Map) return records;
  const map = new Map();
  if (records && typeof records === "object") {
    Object.keys(records).forEach((key) => {
      if (records[key]) map.set(key, records[key]);
    });
  }
  return map;
}

function newRecord(write, rev, actorId, now, data, extra = {}) {
  return {
    key: entityKey(write.kind, write.id),
    kind: write.kind,
    id: write.id,
    rev,
    updatedAt: now,
    actorId: actorId || null,
    deleted: false,
    deletedAt: null,
    data,
    ...extra,
  };
}

function refillsEmptyCourt(storedData, next) {
  const storedPlayers = storedData?.players;
  const nextPlayers = next?.players;
  if (!Array.isArray(storedPlayers) || !Array.isArray(nextPlayers)) return false;
  return storedPlayers.length === 0 && nextPlayers.length > 0;
}

function queuePlayerIds(record) {
  if (!record || record.deleted) return [];
  return Array.isArray(record.data?.playerIds) ? record.data.playerIds : [];
}

function samePlayerSet(left, right) {
  const keyOf = (list) => queueMembership(list).map((id) => String(id)).sort().join(",");
  const a = keyOf(left);
  const b = keyOf(right);
  return a.length > 0 && a === b;
}

function duplicateLiveQueue(records, planned, playerIds, exceptKey) {
  let found = false;
  records.forEach((record) => {
    if (found || !record || record.deleted || record.kind !== "queueItem") return;
    if (record.key === exceptKey) return;
    if (samePlayerSet(record.data?.playerIds, playerIds)) found = true;
  });
  if (found) return true;
  return planned.some((step) => (
    step.type === "write"
    && step.record?.kind === "queueItem"
    && step.record.key !== exceptKey
    && !step.record.deleted
    && samePlayerSet(step.record.data?.playerIds, playerIds)
  ));
}

function replacePlanned(planned, key, step) {
  const index = planned.findIndex((entry) => entry.record.key === key);
  if (index >= 0) planned[index] = step;
  else planned.push(step);
}

/**
 * A player who is not queued cannot stay in a group, and a queued player
 * is not removed by an older depart. Runs only for players this op retargeted.
 */
function alignQueueWithStatus(records, planned, actorId) {
  const statusById = new Map();
  planned.forEach((step) => {
    if (!step.statusTouch || step.record.kind !== "player") return;
    statusById.set(String(step.record.id), step.record.data?.status);
  });
  if (statusById.size === 0) return;

  const queueKeys = new Set();
  records.forEach((record, key) => {
    if (record?.kind === "queueItem") queueKeys.add(key);
  });
  planned.forEach((step) => {
    if (step.record.kind === "queueItem") queueKeys.add(step.record.key);
  });

  const dropped = [];
  queueKeys.forEach((key) => {
    const step = planned.find((entry) => entry.record.key === key);
    if (step?.type === "tombstone") return;
    const stored = records.get(key);
    const storedIds = queuePlayerIds(stored);
    const currentIds = step?.type === "write" ? queuePlayerIds(step.record) : storedIds;
    const seen = new Set();
    const nextIds = [];
    const consider = (id) => {
      const idKey = String(id);
      if (seen.has(idKey)) return;
      seen.add(idKey);
      if (statusById.has(idKey) && statusById.get(idKey) !== "queued") return;
      if (nextIds.length >= QUEUE_PLAYER_CAP) return;
      nextIds.push(id);
    };
    storedIds.forEach(consider);
    currentIds.forEach(consider);
    const same = nextIds.length === currentIds.length && nextIds.every((id, index) => String(id) === String(currentIds[index]));
    if (same) return;
    const id = step?.record?.id ?? stored?.id;
    if (nextIds.length === 0) {
      dropped.push(id);
      if (!stored || stored.deleted) {
        const index = planned.findIndex((entry) => entry.record.key === key);
        if (index >= 0) planned.splice(index, 1);
        return;
      }
      replacePlanned(planned, key, {
        type: "tombstone",
        record: {
          ...stored,
          rev: (Number(stored.rev) || 0) + 1,
          updatedAt: Date.now(),
          actorId: actorId || null,
          deleted: true,
          deletedAt: Date.now(),
          data: null,
        },
      });
      return;
    }
    const data = {
      ...(step?.type === "write" ? step.record.data : stored.data),
      playerIds: nextIds,
    };
    const rev = step?.type === "write" ? step.record.rev : (Number(stored?.rev) || 0) + 1;
    replacePlanned(planned, key, {
      type: "write",
      statusTouch: false,
      record: newRecord({ kind: "queueItem", id }, rev, actorId, Date.now(), data, { rebased: true }),
    });
  });

  if (!dropped.length) return;
  const orderKey = "bundle:queueOrder";
  const orderStep = planned.find((entry) => entry.record.key === orderKey);
  const storedOrder = records.get(orderKey);
  const orderData = orderStep?.record?.data || storedOrder?.data;
  if (!orderData?.ids) return;
  const ids = orderData.ids.filter((id) => !dropped.some((droppedId) => String(droppedId) === String(id)));
  if (ids.length === orderData.ids.length) return;
  const rev = orderStep ? orderStep.record.rev : (Number(storedOrder?.rev) || 0) + 1;
  replacePlanned(planned, orderKey, {
    type: "write",
    record: newRecord({ kind: "bundle", id: "queueOrder" }, rev, actorId, Date.now(), { ...orderData, ids }, {
      rebased: true,
    }),
  });
}

/** Stable physical slot, independent of the editable name and sync identity. */
export function getCalendarCourtId(court) {
  const value = Number(court?.calendarCourtId ?? court?.id);
  return Number.isSafeInteger(value) && value > 0 ? value : null;
}

function durableBaseShape(base, stored) {
  if (!base || !stored || typeof base !== "object" || typeof stored !== "object"
    || Array.isArray(base) || Array.isArray(stored)) return base;
  const shaped = { ...base };
  Object.keys(shaped).forEach(key => {
    if (!Object.prototype.hasOwnProperty.call(stored, key)) delete shaped[key];
    else if (stored[key] == null) shaped[key] = stored[key];
    else shaped[key] = durableBaseShape(shaped[key], stored[key]);
  });
  return shaped;
}

/** Apply one op without mutating the input record map or object. */
export function applyOp(state, op) {
  const records = asMap(state?.records);
  const applied = Array.isArray(state?.appliedOpIds) ? state.appliedOpIds.slice() : [];
  if (!op || !op.opId) return { ok: false, reason: "invalid" };
  if (applied.includes(op.opId)) {
    return {
      ok: true,
      idempotent: true,
      reason: "idempotent",
      records: [],
      tombstones: [],
      appliedOpIds: applied,
      current: Object.fromEntries(records),
    };
  }

  const writes = Array.isArray(op.writes) ? op.writes : [];
  const tombstones = Array.isArray(op.tombstones) ? op.tombstones : [];
  const planned = [];
  const conflicts = [];
  (op.checks || []).forEach((check) => {
    const key = entityKey(check.kind, check.id);
    const storedRev = Number(records.get(key)?.rev) || 0;
    if (storedRev !== (Number(check.baseRev) || 0)) {
      conflicts.push({ key, storedRev, baseRev: Number(check.baseRev) || 0, reason: "snapshot-changed" });
    }
  });

  const consider = (entry) => {
    const key = entityKey(entry.kind, entry.id);
    const stored = records.get(key) || null;
    const storedRev = stored && !stored.deleted ? Number(stored.rev) || 0 : stored?.deleted ? Number(stored.rev) || 0 : 0;
    const baseRev = Number(entry.baseRev);
    const expected = Number.isFinite(baseRev) ? baseRev : 0;
    return { key, stored, storedRev, expected };
  };

  writes.forEach((write) => {
    const { key, stored, storedRev, expected } = consider(write);
    if (stored?.deleted) {
      conflicts.push({ key, storedRev, baseRev: expected, reason: "deleted" });
      return;
    }
    if (!stored) {
      if (expected !== 0) {
        conflicts.push({ key, storedRev: 0, baseRev: expected, reason: "missing" });
        return;
      }
      if (write.kind === "queueItem" && duplicateLiveQueue(records, planned, write.next?.playerIds, key)) {
        conflicts.push({ key, storedRev: 0, baseRev: expected, overlap: ["playerIds"], reason: "duplicate" });
        return;
      }
      planned.push({
        type: "write",
        statusTouch: write.kind === "player" && !deepEqual(write.base?.status, write.next?.status),
        record: newRecord(write, 1, op.actorId, Date.now(), cloneData(write.next)),
      });
      return;
    }
    const journaledBase = write.base != null;
    // React adds defaults to legacy rows. At the same authoritative revision,
    // absent durable fields are normalization, while existing differing values
    // still use the ordinary overlap checks (including same-rev journal replay).
    const baseForRebase = storedRev === expected ? durableBaseShape(write.base, stored.data) : write.base;
    const baseMatches = !journaledBase || deepEqual(stored.data, write.base);
    if (write.kind === "queueItem" && queueMembership(write.next?.playerIds).length > QUEUE_PLAYER_CAP) {
      conflicts.push({ key, storedRev, baseRev: expected, overlap: ["playerIds"], reason: "cap" });
      return;
    }
    if (storedRev === expected && baseMatches) {
      planned.push({
        type: "write",
        statusTouch: write.kind === "player" && !deepEqual(write.base?.status, write.next?.status),
        record: newRecord(write, storedRev + 1, op.actorId, Date.now(), cloneData(write.next)),
      });
      return;
    }
    if (write.kind === "court" && storedRev !== expected && refillsEmptyCourt(stored.data, write.next)) {
      conflicts.push({ key, storedRev, baseRev: expected, overlap: ["players"], reason: "refill" });
      return;
    }
    const rebased = rebaseRecord(stored.data, baseForRebase, write.next);
    if (!rebased.ok) {
      conflicts.push({ key, storedRev, baseRev: expected, overlap: rebased.overlap });
      return;
    }
    if (rebased.noop) return;
    planned.push({
      type: "write",
      statusTouch: write.kind === "player" && !!rebased.statusTouch,
      record: newRecord(write, storedRev + 1, op.actorId, Date.now(), rebased.data, {
        rebased: !!rebased.rebased,
      }),
    });
  });

  tombstones.forEach((tomb) => {
    const { key, stored, storedRev, expected } = consider(tomb);
    if (!stored) {
      if (expected !== 0) {
        conflicts.push({ key, storedRev: 0, baseRev: expected, reason: "missing" });
      }
      return;
    }
    if (stored.deleted) {
      if (storedRev !== expected) {
        conflicts.push({ key, storedRev, baseRev: expected, reason: "deleted" });
      }
      return;
    }
    if (storedRev !== expected) {
      conflicts.push({ key, storedRev, baseRev: expected, reason: "tombstone" });
      return;
    }
    planned.push({
      type: "tombstone",
      record: {
        ...stored,
        rev: storedRev + 1,
        updatedAt: Date.now(),
        actorId: op.actorId || null,
        deleted: true,
        deletedAt: Date.now(),
        data: null,
      },
    });
  });

  // Validate physical-slot uniqueness against the whole transaction's final
  // view. IndexedDB reads all entities in the same read/write transaction.
  // Only new or reassigned courts need validation; unrelated edits must not
  // be blocked by pre-existing legacy state.
  const proposed = new Map(records);
  planned.forEach((step) => proposed.set(step.record.key, step.record));
  const courtRemovals = planned.filter((step) => step.type === "tombstone" && step.record.kind === "court");
  if (courtRemovals.length && !Array.from(proposed.values()).some((record) => record.kind === "court" && !record.deleted)) {
    courtRemovals.forEach((step) => conflicts.push({ key: step.record.key, reason: "last-court" }));
  }
  planned.forEach((step) => {
    const record = step.record;
    if (step.type !== "write" || record.kind !== "court") return;
    const slot = getCalendarCourtId(record.data);
    const previous = records.get(record.key);
    if (slot == null || (previous && getCalendarCourtId(previous.data) === slot)) return;
    const occupied = Array.from(proposed.values()).some((other) =>
      other.kind === "court" && !other.deleted && other.key !== record.key && getCalendarCourtId(other.data) === slot
    );
    if (occupied) conflicts.push({ key: record.key, reason: "calendar-court-taken", calendarCourtId: slot });
  });
  planned.forEach((step) => {
    const record = step.record;
    if (step.type !== "write" || !["court", "queueItem"].includes(record.kind)) return;
    const field = record.kind === "court" ? "players" : "playerIds";
    const ids = queueMembership(record.data?.[field]).map(String);
    if (deepEqual(records.get(record.key)?.data?.[field], record.data?.[field])) return;
    const overlap = Array.from(proposed.values()).some((other) =>
      other.kind === record.kind && !other.deleted && other.key !== record.key
      && queueMembership(other.data?.[field]).some((id) => ids.includes(String(id)))
    );
    if (new Set(ids).size !== ids.length || overlap) {
      conflicts.push({ key: record.key, reason: record.kind === "court" ? "player-on-court" : "duplicate", overlap: [field] });
    }
  });
  planned.forEach((step) => {
    const record = step.record;
    if (step.type !== "write" || record.kind !== "player" || record.data?.status === "playing") return;
    if (records.get(record.key)?.data?.status === record.data?.status) return;
    const releasesCourt = writes.some(write => write.kind === "court"
      && queueMembership(write.base?.players).some(id => String(id) === String(record.id))
      && !queueMembership(write.next?.players).some(id => String(id) === String(record.id)));
    if (record.data?.status !== "queued" && !releasesCourt) return;
    const occupied = Array.from(proposed.values()).some((court) => court.kind === "court" && !court.deleted
      && queueMembership(court.data?.players).some((id) => String(id) === String(record.id)));
    if (occupied) conflicts.push({ key: record.key, reason: "player-on-court", overlap: ["status"] });
  });

  if (conflicts.length > 0) {
    return {
      ok: false,
      reason: "conflict",
      conflicts,
      records: [],
      tombstones: [],
      appliedOpIds: applied,
      current: Object.fromEntries(records),
    };
  }

  alignQueueWithStatus(records, planned, op.actorId);

  const nextRecords = new Map(records);
  const written = [];
  const removed = [];
  planned.forEach((step) => {
    nextRecords.set(step.record.key, step.record);
    if (step.type === "tombstone") removed.push(step.record);
    else written.push(step.record);
  });
  const nextApplied = applied.concat(op.opId).slice(-APPLIED_OP_CAP);
  return {
    ok: true,
    reason: "committed",
    records: written,
    tombstones: removed,
    appliedOpIds: nextApplied,
    current: Object.fromEntries(nextRecords),
    rebased: written.some((record) => record.rebased),
  };
}

function listById(list) {
  const map = new Map();
  (Array.isArray(list) ? list : []).forEach((item) => {
    if (item == null || item.id == null) return;
    map.set(String(item.id), item);
  });
  return map;
}

function pushWrite(writes, kind, id, revMap, base, next) {
  const key = entityKey(kind, id);
  const baseRev = Number(revMap?.get?.(key) ?? revMap?.[key] ?? 0) || 0;
  writes.push({
    kind,
    id,
    baseRev,
    base: cloneData(base),
    next: cloneData(next),
  });
}

function diffList(kind, baseList, nextList, revMap, writes, tombstones) {
  const baseMap = listById(baseList);
  const nextMap = listById(nextList);
  nextMap.forEach((item, id) => {
    const prev = baseMap.get(id);
    if (prev === item) return;
    if (prev && deepEqual(prev, item)) return;
    pushWrite(writes, kind, item.id, revMap, prev || null, item);
  });
  baseMap.forEach((item, id) => {
    if (nextMap.has(id)) return;
    const key = entityKey(kind, item.id);
    tombstones.push({
      kind,
      id: item.id,
      baseRev: Number(revMap?.get?.(key) ?? revMap?.[key] ?? 0) || 0,
    });
  });
}

function diffSingleton(kind, id, base, next, revMap, writes) {
  if (base === next) return;
  if (deepEqual(base, next)) return;
  pushWrite(writes, kind, id, revMap, base, next);
}

let opCounter = 0;

export function createOpId(actorId) {
  opCounter += 1;
  const rand = Math.random().toString(36).slice(2, 8);
  return `${actorId || "tab"}:${Date.now().toString(36)}:${opCounter.toString(36)}:${rand}`;
}

/**
 * Build one op from the last committed document and the desired cache.
 * Unchanged object references are skipped, so a court click does not walk match history.
 */
export function buildOpFromDiff(baseDoc, nextDoc, revMap, actorId, opId) {
  const base = baseDoc || {};
  const next = nextDoc || {};
  const writes = [];
  const tombstones = [];
  diffList("court", base.courts, next.courts, revMap, writes, tombstones);
  diffList("player", base.players, next.players, revMap, writes, tombstones);
  diffList("queueItem", base.matchQueue, next.matchQueue, revMap, writes, tombstones);
  diffList("match", base.matches, next.matches, revMap, writes, tombstones);
  diffList("session", base.opSessions, next.opSessions, revMap, writes, tombstones);
  diffSingleton("settings", "club", base.settings || null, next.settings || null, revMap, writes);
  // recentHold stays so a missing field is a no-op. South Dinkers does not create hold rows.
  diffSingleton("hold", "recent", base.recentHold || null, next.recentHold || null, revMap, writes);
  diffSingleton(
    "bundle",
    "partners",
    { list: base.partners || [] },
    { list: next.partners || [] },
    revMap,
    writes
  );
  diffSingleton(
    "bundle",
    "teams",
    { list: base.teams || [] },
    { list: next.teams || [] },
    revMap,
    writes
  );
  diffSingleton(
    "bundle",
    "requested",
    { list: base.requestedMatches || [] },
    { list: next.requestedMatches || [] },
    revMap,
    writes
  );
  diffSingleton(
    "bundle",
    "queueOrder",
    { ids: (base.matchQueue || []).map((item) => item.id) },
    { ids: (next.matchQueue || []).map((item) => item.id) },
    revMap,
    writes
  );
  diffSingleton(
    "bundle",
    "courtOrder",
    { ids: (base.courts || []).map((item) => item.id) },
    { ids: (next.courts || []).map((item) => item.id) },
    revMap,
    writes
  );
  diffSingleton(
    "bundle",
    "playerOrder",
    { ids: (base.players || []).map((item) => item.id) },
    { ids: (next.players || []).map((item) => item.id) },
    revMap,
    writes
  );
  diffSingleton(
    "bundle",
    "matchOrder",
    { ids: (base.matches || []).map((item) => item.id) },
    { ids: (next.matches || []).map((item) => item.id) },
    revMap,
    writes
  );
  diffSingleton(
    "bundle",
    "currentSession",
    { id: base.currentOpSession?.id ?? null },
    { id: next.currentOpSession?.id ?? null },
    revMap,
    writes
  );

  if (!writes.length && !tombstones.length) return null;
  const snapshotsSession = writes.some((write) => write.kind === "session"
    && ["completed", "cancelled"].includes(write.next?.status)
    && write.id === base.currentOpSession?.id);
  const checks = [];
  if (snapshotsSession) {
    const check = (kind, id) => checks.push({ kind, id, baseRev: Number(revMap?.get?.(entityKey(kind, id)) ?? revMap?.[entityKey(kind, id)] ?? 0) || 0 });
    [["court", base.courts], ["player", base.players], ["match", base.matches]].forEach(([kind, list]) => (list || []).forEach((row) => check(kind, row.id)));
    ["courtOrder", "playerOrder", "matchOrder", "currentSession"].forEach(id => check("bundle", id));
    check("settings", "club");
  }
  return {
    opId: opId || createOpId(actorId),
    actorId: actorId || null,
    writes,
    tombstones,
    ...(checks.length ? { checks } : {}),
  };
}

/**
 * Stat, settings, and rental-lock edits must not share an op with a user action.
 * Returns the user op, or the original when the snapshot is only incidental.
 */
export function focusUserOp(op) {
  if (!op) return { op: null, partial: false };
  const writes = [];
  let dropped = false;
  (op.writes || []).forEach((write) => {
    if (write.kind === "settings") {
      const fields = changedKeys(write.base, write.next);
      if (fields.length && fields.every(key => ["teamsModeEnabled", "teams"].includes(key))) {
        writes.push(write);
        return;
      }
      dropped = true;
      return;
    }
    const changed = changedKeys(write.base, write.next);
    const kept = changed.filter((key) => !isIncidentalField(key));
    if (!kept.length) {
      if (changed.length) dropped = true;
      return;
    }
    if (kept.length === changed.length) {
      writes.push(write);
      return;
    }
    const next = cloneData(write.next);
    changed.forEach((key) => {
      if (kept.includes(key)) return;
      if (write.base && Object.prototype.hasOwnProperty.call(write.base, key)) next[key] = cloneData(write.base[key]);
      else delete next[key];
    });
    writes.push({ ...write, next });
    dropped = true;
  });
  const tombstones = op.tombstones || [];
  if (!writes.length && !tombstones.length) return { op, partial: false };
  if (!dropped) return { op, partial: false };
  return {
    op: { ...op, writes, tombstones },
    partial: true,
  };
}

export function opTouchesOnlyResults(op) {
  const writes = op?.writes || [];
  const tombstones = op?.tombstones || [];
  const writeOk = writes.every((write) =>
    write.kind === "match" || write.kind === "session" || write.kind === "player" || write.kind === "hold"
  );
  const tombOk = tombstones.every((tomb) => tomb.kind === "match");
  return writeOk && tombOk && (writes.length > 0 || tombstones.length > 0);
}

function sortByOrder(list, orderIds) {
  if (!Array.isArray(orderIds) || orderIds.length === 0) return list;
  const rank = new Map(orderIds.map((id, index) => [String(id), index]));
  return list.slice().sort((a, b) => {
    const ar = rank.has(String(a.id)) ? rank.get(String(a.id)) : Number.MAX_SAFE_INTEGER;
    const br = rank.has(String(b.id)) ? rank.get(String(b.id)) : Number.MAX_SAFE_INTEGER;
    if (ar !== br) return ar - br;
    return 0;
  });
}

/** Project entity records into the React document shape. Deleted records are omitted. */
export function projectEntities(records) {
  const list = records instanceof Map ? Array.from(records.values()) : Object.values(records || {});
  const live = list.filter((record) => record && !record.deleted && record.kind !== "meta");
  const byKind = (kind) => live.filter((record) => record.kind === kind);
  const bundle = (id) => byKind("bundle").find((record) => String(record.id) === id)?.data || null;
  const settings = byKind("settings").find((record) => String(record.id) === "club")?.data || null;
  const hold = byKind("hold").find((record) => String(record.id) === "recent")?.data || null;
  const sessions = byKind("session").map((record) => record.data).filter(Boolean);
  const pointer = bundle("currentSession");
  const pointed = pointer?.id != null
    ? sessions.find((session) => String(session.id) === String(pointer.id)) || null
    : null;
  const pointedStatus = String(pointed?.status || "").toLowerCase();
  const current = pointed && pointedStatus !== "completed" && pointedStatus !== "cancelled" && !pointed.endedAt
    ? pointed
    : null;
  const queue = byKind("queueItem").map((record) => record.data).filter(Boolean);
  const entityRevs = {};
  list.forEach((record) => {
    if (record?.key) entityRevs[record.key] = record.rev || 0;
  });
  live.forEach((record) => {
    if (record?.key) entityRevs[record.key] = record.rev || 0;
  });
  return {
    courts: sortByOrder(byKind("court").map((record) => record.data).filter(Boolean), bundle("courtOrder")?.ids),
    players: sortByOrder(byKind("player").map((record) => record.data).filter(Boolean), bundle("playerOrder")?.ids),
    matchQueue: sortByOrder(queue, bundle("queueOrder")?.ids),
    matches: sortByOrder(byKind("match").map((record) => record.data).filter(Boolean), bundle("matchOrder")?.ids),
    opSessions: sessions,
    currentOpSession: current,
    settings: settings || {},
    recentHold: hold,
    partners: bundle("partners")?.list || [],
    teams: bundle("teams")?.list || [],
    requestedMatches: bundle("requested")?.list || [],
    userRole: bundle("identity")?.userRole ?? null,
    staffName: bundle("identity")?.staffName ?? "",
    entityRevs,
  };
}

const LEGACY_LEVELS = {
  Intermediate: "H.Inter",
  Advanced: "Advance",
};

function migrateBackfillPlayer(player) {
  if (!player || typeof player !== "object") return player;
  const level = LEGACY_LEVELS[player.level];
  if (!level) return player;
  return { ...player, level };
}

function putRecord(records, kind, id, data, rev = 1) {
  if (data == null) return;
  const key = entityKey(kind, id);
  records.push({
    key,
    kind,
    id,
    rev,
    updatedAt: Date.now(),
    actorId: "migration",
    deleted: false,
    deletedAt: null,
    data: cloneData(data),
  });
}

/** One-time copy of a kv/appState document into entity records at rev 1. */
export function backfillRecordsFromDocument(doc) {
  const records = [];
  const state = doc || {};
  (state.courts || []).forEach((court) => {
    if (court?.id == null) return;
    putRecord(records, "court", court.id, court);
  });
  (state.players || []).forEach((player) => {
    if (player?.id == null) return;
    putRecord(records, "player", player.id, migrateBackfillPlayer(player));
  });
  (state.matchQueue || []).forEach((item) => {
    if (item?.id == null) return;
    putRecord(records, "queueItem", item.id, item);
  });
  (state.matches || []).forEach((match) => {
    if (match?.id == null) return;
    putRecord(records, "match", match.id, match);
  });
  (state.opSessions || []).forEach((session) => {
    if (session?.id == null) return;
    putRecord(records, "session", session.id, session);
  });
  if (state.settings && typeof state.settings === "object") {
    putRecord(records, "settings", "club", state.settings);
  }
  putRecord(records, "bundle", "partners", { list: state.partners || [] });
  putRecord(records, "bundle", "teams", { list: state.teams || [] });
  putRecord(records, "bundle", "requested", { list: state.requestedMatches || [] });
  putRecord(records, "bundle", "queueOrder", {
    ids: (state.matchQueue || []).map((item) => item.id),
  });
  putRecord(records, "bundle", "courtOrder", {
    ids: (state.courts || []).map((item) => item.id),
  });
  putRecord(records, "bundle", "playerOrder", {
    ids: (state.players || []).map((item) => item.id),
  });
  putRecord(records, "bundle", "matchOrder", {
    ids: (state.matches || []).map((item) => item.id),
  });
  putRecord(records, "bundle", "currentSession", {
    id: state.currentOpSession?.id ?? null,
  });
  return records;
}

export function countLiveRecords(records) {
  const list = records instanceof Map ? Array.from(records.values()) : Object.values(records || {});
  return list.filter((record) => record && !record.deleted && record.kind !== "meta").length;
}

/**
 * Merge a newer remote record onto a pending local edit without dropping
 * fields this window already changed and has not acked yet.
 */
export function mergeRemoteOntoPending(committed, local, incoming) {
  if (!local || local === incoming) return incoming;
  const ours = changedKeys(committed, local);
  if (ours.length === 0) return incoming;
  const merged = cloneData(incoming);
  ours.forEach((key) => {
    merged[key] = cloneData(local[key]);
  });
  return merged;
}

/**
 * Settings rows from backfill are a subset of the normalized club settings.
 * Keep keys the incoming row does not carry (GCash name, fee defaults) and
 * still take every key the incoming row does carry.
 */
export function mergeSettings(committed, local, incoming) {
  const merged = mergeRemoteOntoPending(committed || {}, local || {}, incoming || {});
  if (!merged || typeof merged !== "object" || Array.isArray(merged)) return merged || {};
  [local, committed].forEach((source) => {
    if (!source || typeof source !== "object") return;
    Object.keys(source).forEach((key) => {
      if (Object.prototype.hasOwnProperty.call(incoming || {}, key)) return;
      if (Object.prototype.hasOwnProperty.call(merged, key)) return;
      merged[key] = cloneData(source[key]);
    });
  });
  return merged;
}

function indexById(list) {
  const map = new Map();
  (Array.isArray(list) ? list : []).forEach((item) => {
    if (item == null || item.id == null) return;
    map.set(String(item.id), item);
  });
  return map;
}

/**
 * Fold a remote list onto the rows React already has.
 * A field this window changed and has not acked stays. A remote tombstone
 * drops a row only when this window has not edited it. Local-only rows stay.
 */
export function mergeRemoteList(prev, baseList, remoteList) {
  const baseById = indexById(baseList);
  const prevList = Array.isArray(prev) ? prev : [];
  const prevById = indexById(prevList);
  const remote = Array.isArray(remoteList) ? remoteList : [];
  const remoteById = indexById(remote);
  const out = [];
  remote.forEach((remoteItem) => {
    if (remoteItem == null || remoteItem.id == null) return;
    const id = String(remoteItem.id);
    const merged = mergeRemoteOntoPending(baseById.get(id), prevById.get(id), remoteItem);
    if (merged) out.push(merged);
  });
  prevList.forEach((localItem) => {
    if (localItem == null || localItem.id == null) return;
    const id = String(localItem.id);
    if (remoteById.has(id)) return;
    const baseItem = baseById.get(id);
    if (!baseItem || changedKeys(baseItem, localItem).length > 0) out.push(localItem);
  });
  return out;
}

/** Remote null clears a singleton only when this window has not edited it. */
export function mergeRemoteValue(base, local, remote) {
  if (remote == null) {
    if (base == null) return local ?? null;
    if (local == null || changedKeys(base, local).length === 0) return null;
    return local;
  }
  if (local == null) return remote;
  return mergeRemoteOntoPending(base, local, remote);
}

export function snapshotDirty(base, next) {
  return buildOpFromDiff(base, next, new Map(), "dirty-check") != null;
}

export function changedEntityKeys(baseDoc, nextDoc) {
  const op = buildOpFromDiff(baseDoc, nextDoc, new Map(), "pending");
  const keys = new Set();
  (op?.writes || []).forEach((write) => keys.add(entityKey(write.kind, write.id)));
  (op?.tombstones || []).forEach((tomb) => keys.add(entityKey(tomb.kind, tomb.id)));
  return keys;
}

const LIST_FIELDS = {
  court: "courts",
  player: "players",
  queueItem: "matchQueue",
  match: "matches",
  session: "opSessions",
};

function findById(list, id) {
  return (list || []).find((item) => item && String(item.id) === String(id)) || null;
}

function blankDocument(doc) {
  const source = doc || {};
  return {
    courts: (source.courts || []).slice(),
    players: (source.players || []).slice(),
    matchQueue: (source.matchQueue || []).slice(),
    matches: (source.matches || []).slice(),
    opSessions: (source.opSessions || []).slice(),
    currentOpSession: source.currentOpSession ?? null,
    settings: source.settings || {},
    recentHold: source.recentHold || null,
    partners: (source.partners || []).slice(),
    teams: (source.teams || []).slice(),
    requestedMatches: (source.requestedMatches || []).slice(),
    userRole: source.userRole ?? null,
    staffName: source.staffName ?? "",
  };
}

function replaceListItem(list, id, data) {
  const idx = list.findIndex((item) => item && String(item.id) === String(id));
  if (data == null) {
    if (idx >= 0) list.splice(idx, 1);
    return;
  }
  if (idx >= 0) list[idx] = data;
  else list.push(data);
}

function applyOrder(list, ids) {
  if (!Array.isArray(ids)) return list;
  return sortByOrder(list, ids);
}

/**
 * Fold committed records into a cache document.
 * Pending local edits keep the fields this window changed.
 * Older revs are ignored unless `force` (conflict resolution).
 */
export function integrateRecords({
  committed,
  live,
  records = [],
  tombstones = [],
  revMap,
  pendingKeys,
  force = false,
}) {
  const pending = pendingKeys instanceof Set ? pendingKeys : new Set(pendingKeys || []);
  const next = blankDocument(live || committed || {});
  let changed = false;

  const accept = (record) => {
    if (!record?.kind || record.kind === "meta") return false;
    const key = record.key || entityKey(record.kind, record.id);
    const known = revMap?.get?.(key) ?? 0;
    if (!force && !shouldApplyRev(known, record.rev)) return false;
    if (revMap?.set) revMap.set(key, Number(record.rev) || 0);
    changed = true;
    return true;
  };

  const all = records.concat(tombstones || []);
  // Sessions and queue rows land before the bundles that point at them.
  // Otherwise a current-session pointer resolves against a missing session,
  // and queue order sorts an empty list.
  const rank = (record) => {
    if (record?.kind === "bundle" && String(record.id) === "currentSession") return 3;
    if (record?.kind === "bundle" && String(record.id).endsWith("Order")) return 2;
    if (record?.kind === "bundle") return 1;
    return 0;
  };
  all.slice().sort((a, b) => rank(a) - rank(b)).forEach((record) => {
    if (record?.kind === "bundle" && String(record.id) === "identity") return;
    if (!accept(record)) return;
    const field = LIST_FIELDS[record.kind];
    if (field) {
      let data = record.deleted ? null : record.data;
      const key = record.key || entityKey(record.kind, record.id);
      if (data && pending.has(key)) {
        data = mergeRemoteOntoPending(
          findById(committed?.[field], record.id),
          findById(live?.[field], record.id),
          data
        );
      }
      replaceListItem(next[field], record.id, data);
      return;
    }
    if (record.deleted) return;
    if (record.kind === "settings" && String(record.id) === "club") {
      const key = record.key || entityKey("settings", "club");
      const local = pending.has(key) ? live?.settings : committed?.settings;
      next.settings = mergeSettings(committed?.settings, local, record.data || {});
      return;
    }
    if (record.kind === "hold" && String(record.id) === "recent") {
      next.recentHold = record.data || next.recentHold;
      return;
    }
    if (record.kind === "bundle" && String(record.id) === "partners") next.partners = record.data?.list || [];
    if (record.kind === "bundle" && String(record.id) === "teams") next.teams = record.data?.list || [];
    if (record.kind === "bundle" && String(record.id) === "requested") next.requestedMatches = record.data?.list || [];
    if (record.kind === "bundle" && String(record.id) === "queueOrder") {
      next.matchQueue = applyOrder(next.matchQueue, record.data?.ids);
    }
    if (record.kind === "bundle" && String(record.id) === "courtOrder") {
      next.courts = applyOrder(next.courts, record.data?.ids);
    }
    if (record.kind === "bundle" && String(record.id) === "playerOrder") {
      next.players = applyOrder(next.players, record.data?.ids);
    }
    if (record.kind === "bundle" && String(record.id) === "matchOrder") {
      next.matches = applyOrder(next.matches, record.data?.ids);
    }
    if (record.kind === "bundle" && String(record.id) === "currentSession") {
      const id = record.data?.id;
      if (id == null) next.currentOpSession = null;
      else {
        const session = findById(next.opSessions, id);
        const status = String(session?.status || "").toLowerCase();
        next.currentOpSession = session && status !== "completed" && status !== "cancelled" && !session.endedAt
          ? session
          : null;
      }
    }
  });

  if (next.currentOpSession?.id != null) {
    const fresh = findById(next.opSessions, next.currentOpSession.id);
    if (fresh) {
      const status = String(fresh.status || "").toLowerCase();
      next.currentOpSession = status === "completed" || status === "cancelled" || fresh.endedAt ? null : fresh;
    }
  }

  return { doc: next, changed };
}

/**
 * Put a failed op's entities back on the last acked document.
 * Fields edited after that op was built stay on top of the restored rows.
 */
export function revertFailedOp(latest, committed, op) {
  const next = blankDocument(latest || {});
  // Do not turn an absent, untouched singleton into a new settings write.
  next.settings = latest?.settings;
  const saved = committed || {};
  const writes = op?.writes || [];
  const tombs = op?.tombstones || [];

  const restoreValue = (captured, local, acknowledged) => {
    if (deepEqual(captured, local)) return cloneData(acknowledged);
    // A deletion after the captured write is a separate pending edit.
    if (local == null && captured != null) return local;
    if (acknowledged == null) {
      if (captured == null || typeof local !== "object") return cloneData(local);
      const later = {};
      changedKeys(captured, local).forEach((key) => {
        if (Object.prototype.hasOwnProperty.call(local, key)) later[key] = cloneData(local[key]);
      });
      return Object.keys(later).length ? later : null;
    }
    return mergeRemoteOntoPending(captured, local, acknowledged);
  };

  const restoreOrder = (rows, capturedIds = [], localIds = [], acknowledgedIds = []) => {
    const present = new Set(rows.map((row) => String(row.id)));
    const local = new Set(localIds.map(String));
    const captured = new Set(capturedIds.map(String));
    const capturedSurvivors = capturedIds.map(String).filter((id) => local.has(id) && present.has(id));
    const localSurvivors = localIds.map(String).filter((id) => captured.has(id) && present.has(id));
    // Restore the failed reorder unless the user reordered again afterwards.
    return applyOrder(rows, deepEqual(capturedSurvivors, localSurvivors) ? acknowledgedIds : localIds);
  };

  const restoreBundleList = (captured = [], local = [], acknowledged = []) => {
    const capturedRows = listById(captured);
    const localRows = listById(local);
    const acknowledgedRows = listById(acknowledged);
    const restored = new Map(acknowledged.map((row) => [String(row.id), cloneData(row)]));
    capturedRows.forEach((row, id) => {
      if (!localRows.has(id) || !acknowledgedRows.has(id)) restored.delete(id);
      else restored.set(id, restoreValue(row, localRows.get(id), acknowledgedRows.get(id)));
    });
    localRows.forEach((row, id) => {
      if (capturedRows.has(id)) return;
      restored.set(id, restoreValue(null, row, acknowledgedRows.get(id) ?? null));
    });
    return restoreOrder(
      Array.from(restored.values()).filter(Boolean),
      captured.map((row) => row.id), local.map((row) => row.id), acknowledged.map((row) => row.id)
    );
  };

  const restoreId = (kind, id) => {
    const field = LIST_FIELDS[kind];
    if (!field) return;
    const write = writes.find((entry) => entry.kind === kind && String(entry.id) === String(id));
    const local = findById(latest?.[field], id);
    const baseItem = findById(saved[field], id);
    const acknowledged = Array.isArray(saved[field]) ? baseItem : write?.base ?? null;
    if (acknowledged) {
      const restored = restoreValue(write?.next ?? null, local, acknowledged);
      replaceListItem(next[field], id, restored);
      return;
    }
    if (write) {
      replaceListItem(next[field], id, null);
      return;
    }
    replaceListItem(next[field], id, null);
  };

  writes.forEach((write) => restoreId(write.kind, write.id));
  tombs.forEach((tomb) => restoreId(tomb.kind, tomb.id));

  const touched = writes.concat(tombs);
  const touchedWrite = (kind, id) => writes.find((write) => write.kind === kind && String(write.id) === id);
  const touches = (kind, id) => touched.some((entry) => entry.kind === kind && String(entry.id) === id);
  if (touches("settings", "club")) {
    const write = touchedWrite("settings", "club");
    const acknowledged = Object.prototype.hasOwnProperty.call(saved, "settings") ? saved.settings : write?.base ?? null;
    next.settings = restoreValue(write?.next ?? null, latest?.settings, acknowledged);
  }
  if (touches("hold", "recent")) {
    const write = touchedWrite("hold", "recent");
    const acknowledged = Object.prototype.hasOwnProperty.call(saved, "recentHold") ? saved.recentHold : write?.base ?? null;
    next.recentHold = restoreValue(write?.next ?? null, latest?.recentHold, acknowledged);
  }

  const bundleLists = { partners: "partners", teams: "teams", requested: "requestedMatches" };
  Object.entries(bundleLists).forEach(([id, field]) => {
    if (!touches("bundle", id)) return;
    const write = touchedWrite("bundle", id);
    next[field] = restoreBundleList(write?.next?.list || [], latest?.[field] || [], saved[field] ?? write?.base?.list ?? []);
  });
  const orders = { queueOrder: "matchQueue", courtOrder: "courts", playerOrder: "players", matchOrder: "matches" };
  Object.entries(orders).forEach(([id, field]) => {
    if (!touches("bundle", id)) return;
    const write = touchedWrite("bundle", id);
    next[field] = restoreOrder(next[field], write?.next?.ids || [], (latest?.[field] || []).map((row) => row.id), (saved[field] || []).map((row) => row.id));
  });
  if (touches("bundle", "identity")) {
    const write = touchedWrite("bundle", "identity");
    const identity = restoreValue(write?.next ?? { userRole: null, staffName: "" },
      { userRole: latest?.userRole ?? null, staffName: latest?.staffName ?? "" },
      { userRole: saved.userRole ?? null, staffName: saved.staffName ?? "" });
    next.userRole = identity?.userRole ?? null;
    next.staffName = identity?.staffName ?? "";
  }
  if (touches("bundle", "currentSession")) {
    const write = touchedWrite("bundle", "currentSession");
    const capturedId = write?.next?.id ?? null;
    const localId = latest?.currentOpSession?.id ?? null;
    const desired = String(localId) === String(capturedId) ? saved.currentOpSession : latest?.currentOpSession;
    next.currentOpSession = desired?.id != null ? findById(next.opSessions, desired.id) || desired : null;
  }
  return next;
}
