import config from "../../config";

const API_BASE = process.env.REACT_APP_API_URL || "";
const FACILITY_ID = process.env.REACT_APP_FACILITY_ID || config.facilityId;

const parseJson = async (res) => {
  try {
    return await res.json();
  } catch {
    return {};
  }
};

export async function fetchFacilitySettings() {
  const res = await fetch(`${API_BASE}/api/v1/facilities/${FACILITY_ID}/settings`);
  const data = await parseJson(res);
  if (!res.ok) {
    const err = new Error(data.message || data.error || "Could not load settings");
    err.code = data.error;
    throw err;
  }
  return data;
}

export async function fetchInvoiceSettings() {
  const res = await fetch(`${API_BASE}/api/v1/facilities/${FACILITY_ID}/invoice`);
  const data = await parseJson(res);
  if (!res.ok) {
    const err = new Error(data.message || data.error || "Could not load GCash settings");
    err.code = data.error;
    throw err;
  }
  return data;
}

export async function saveFacilitySettings(calendarSettings) {
  const res = await fetch(`${API_BASE}/api/v1/facilities/${FACILITY_ID}/settings`, {
    method: "PUT",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ calendar_settings: calendarSettings }),
  });
  const data = await parseJson(res);
  if (!res.ok) {
    const err = new Error(data.message || data.error || "Could not save settings");
    err.code = data.error;
    throw err;
  }
  return data;
}
