import React from "react";

/** Team Settings form — `teams` is settings.teams (toggles), not the team list */
export default function TeamsSettingsPanel({ teamsSettings, onChange, idPrefix = "ts" }) {
  const t = teamsSettings || {};
  return (
    <div className="space-y-4 text-left text-xs text-slate-700">
      <div>
        <h4 className="text-[11px] font-semibold text-slate-800 mb-2">Matching</h4>
        <div className="space-y-2">
          <label className="flex items-center justify-between gap-2">
            <span>Level mode</span>
            <select
              className="border rounded px-2 py-1 text-xs"
              value={t.levelMode || "balanced"}
              onChange={(e) => onChange({ levelMode: e.target.value })}
            >
              <option value="balanced">Balanced (sum of levels)</option>
              <option value="strict">Strict (per-side spread ≤ 1)</option>
            </select>
          </label>
          <label className="flex items-center justify-between gap-2">
            <span>Pair rotation strength</span>
            <select
              className="border rounded px-2 py-1 text-xs"
              value={t.pairRotationStrength || "normal"}
              onChange={(e) => onChange({ pairRotationStrength: e.target.value })}
            >
              <option value="normal">Normal</option>
              <option value="strong">Strong</option>
            </select>
          </label>
          <label className="flex items-center gap-2 cursor-pointer">
            <input
              id={`${idPrefix}-r3`}
              type="checkbox"
              checked={t.enforceSessionRepeatThreePlayer !== false}
              onChange={(e) => onChange({ enforceSessionRepeatThreePlayer: e.target.checked })}
            />
            <span>Block same-session 3-player repeat</span>
          </label>
          <label className="flex items-center gap-2 cursor-pointer">
            <input
              id={`${idPrefix}-r4`}
              type="checkbox"
              checked={t.enforceSessionRepeatFourExact !== false}
              onChange={(e) => onChange({ enforceSessionRepeatFourExact: e.target.checked })}
            />
            <span>Block exact same 4 players repeat (session)</span>
          </label>
        </div>
      </div>

      <div>
        <h4 className="text-[11px] font-semibold text-slate-800 mb-2">Display (TV)</h4>
        <label className="flex items-center gap-2 cursor-pointer mb-2">
          <input
            type="checkbox"
            checked={t.showTopTeamsOnDisplay !== false}
            onChange={(e) => onChange({ showTopTeamsOnDisplay: e.target.checked })}
          />
          <span>Show Top Teams / Team of the Day</span>
        </label>
        <label className="flex items-center justify-between gap-2">
          <span>Runner-up rows</span>
          <select
            className="border rounded px-2 py-1 text-xs"
            value={Number(t.topTeamsRunnerUpCount ?? 2)}
            onChange={(e) => onChange({ topTeamsRunnerUpCount: Number(e.target.value) })}
          >
            <option value={0}>0</option>
            <option value={1}>1</option>
            <option value={2}>2</option>
          </select>
        </label>
        <label className="flex items-center justify-between gap-2 mt-2">
          <span>Ranking</span>
          <select
            className="border rounded px-2 py-1 text-xs"
            value={t.topTeamsRankingMode || "winsFirst"}
            onChange={(e) => onChange({ topTeamsRankingMode: e.target.value })}
          >
            <option value="winsFirst">Wins first</option>
            <option value="winRateFirst">Win rate first</option>
          </select>
        </label>
      </div>

      <div>
        <h4 className="text-[11px] font-semibold text-slate-800 mb-2">Proposals</h4>
        <label className="flex items-center gap-2 cursor-pointer">
          <input
            type="checkbox"
            checked={t.showVersusDisclaimer !== false}
            onChange={(e) => onChange({ showVersusDisclaimer: e.target.checked })}
          />
          <span>Show pairing-repeat disclaimer on versus proposal</span>
        </label>
      </div>

      <div>
        <h4 className="text-[11px] font-semibold text-slate-800 mb-2">Labels</h4>
        <label className="block">
          <span className="text-slate-500">Unassigned bucket name</span>
          <input
            type="text"
            className="mt-1 w-full border rounded px-2 py-1 text-xs"
            value={t.unassignedLabel ?? "Unassigned"}
            onChange={(e) => onChange({ unassignedLabel: e.target.value })}
          />
        </label>
      </div>
    </div>
  );
}
