import React, { useCallback, useState } from "react";
import LockScreen from "./LockScreen";
import { isE2EMode } from "../../state/e2eMode";

/**
 * In-memory kiosk lock. Unlock does not survive refresh or reload.
 * Playwright may pass ?e2e=1 outside production builds.
 */
export default function SiteLockGate({ children }) {
  const [unlocked, setUnlocked] = useState(() => process.env.NODE_ENV === "test" || isE2EMode());
  const handleUnlock = useCallback(() => setUnlocked(true), []);

  if (!unlocked) {
    return <LockScreen onUnlock={handleUnlock} />;
  }

  return children;
}
