import React, { useState } from 'react';
import { FileText, Printer, X, Loader2 } from 'lucide-react';
import { useNavigate } from 'react-router-dom';

export default function ReportGenerationModal({ isOpen, onClose }) {
    const navigate = useNavigate();
    const d = new Date();
    const localYMD = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
    const localMonth = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;

    const [mode, setMode] = useState('day'); // 'day' | 'range' | 'month'
    const [date, setDate] = useState(localYMD);
    const [startDate, setStartDate] = useState(localYMD);
    const [endDate, setEndDate] = useState(localYMD);
    const [month, setMonth] = useState(localMonth); // YYYY-MM

    const [isGenerating, setIsGenerating] = useState(false);

    if (!isOpen) return null;

    const handleGenerate = () => {
        setIsGenerating(true);
        // Simulate loading for "flair"
        setTimeout(() => {
            const params = new URLSearchParams();
            params.set('mode', mode);
            if (mode === 'day') params.set('date', date);
            if (mode === 'range') {
                params.set('start', startDate);
                params.set('end', endDate);
            }
            if (mode === 'month') params.set('month', month);

            navigate(`/reports/print?${params.toString()}`);
            setIsGenerating(false);
            onClose();
        }, 1500);
    };

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4 animate-in fade-in duration-200">
            <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md overflow-hidden relative">
                {/* Header */}
                <div className="bg-white p-6 text-pt-teal relative overflow-hidden border-b border-pt-teal/10">
                    {/* Decorative Blob */}
                    <div className="absolute top-0 right-0 w-32 h-32 bg-pt-teal rounded-full blur-3xl opacity-10 -mr-16 -mt-16 pointer-events-none"></div>
                    <div className="relative z-10">
                        <h2 className="text-2xl font-bold flex items-center gap-3 font-body">
                            <Printer className="w-6 h-6 text-pt-teal" />
                            Generate Report
                        </h2>
                        <p className="text-pt-teal/60 text-sm mt-1">Export detailed facility analytics</p>
                    </div>
                    <button
                        onClick={onClose}
                        className="absolute top-4 right-4 p-2 hover:bg-pt-teal/10 rounded-full transition-colors text-pt-teal"
                    >
                        <X className="w-4 h-4" />
                    </button>
                </div>

                {/* Body */}
                <div className="p-6 space-y-6">
                    {/* Mode Selection */}
                    <div className="space-y-3">
                        <label className="text-xs font-bold text-pt-teal/60 uppercase tracking-wide">Report Type</label>
                        <div className="grid grid-cols-3 gap-2 bg-white p-1 rounded-xl border border-pt-teal/5">
                            <button
                                onClick={() => setMode('day')}
                                className={`px-4 py-2 rounded-lg text-sm font-medium transition-all ${mode === 'day' ? 'bg-pt-teal text-white shadow-md' : 'text-pt-teal/60 hover:text-pt-teal'}`}
                            >
                                Daily
                            </button>
                            <button
                                onClick={() => setMode('range')}
                                className={`px-4 py-2 rounded-lg text-sm font-medium transition-all ${mode === 'range' ? 'bg-pt-teal text-white shadow-md' : 'text-pt-teal/60 hover:text-pt-teal'}`}
                            >
                                Range
                            </button>
                            <button
                                onClick={() => setMode('month')}
                                className={`px-4 py-2 rounded-lg text-sm font-medium transition-all ${mode === 'month' ? 'bg-pt-teal text-white shadow-md' : 'text-pt-teal/60 hover:text-pt-teal'}`}
                            >
                                Monthly
                            </button>
                        </div>
                    </div>

                    {/* Inputs */}
                    <div className="space-y-4">
                        {mode === 'day' && (
                            <div>
                                <label className="block text-sm font-medium text-slate-700 mb-2">Select Date</label>
                                <input
                                    type="date"
                                    value={date}
                                    onChange={(e) => setDate(e.target.value)}
                                    className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-lg text-slate-900 focus:outline-none focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 transition-all font-mono"
                                />
                            </div>
                        )}

                        {mode === 'range' && (
                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-sm font-medium text-slate-700 mb-2">Start Date</label>
                                    <input
                                        type="date"
                                        value={startDate}
                                        onChange={(e) => setStartDate(e.target.value)}
                                        className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-lg text-slate-900 focus:outline-none focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 transition-all font-mono"
                                    />
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-slate-700 mb-2">End Date</label>
                                    <input
                                        type="date"
                                        value={endDate}
                                        onChange={(e) => setEndDate(e.target.value)}
                                        className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-lg text-slate-900 focus:outline-none focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 transition-all font-mono"
                                    />
                                </div>
                            </div>
                        )}

                        {mode === 'month' && (
                            <div>
                                <label className="block text-sm font-medium text-slate-700 mb-2">Select Month</label>
                                <input
                                    type="month"
                                    value={month}
                                    onChange={(e) => setMonth(e.target.value)}
                                    className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-lg text-slate-900 focus:outline-none focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 transition-all font-mono"
                                />
                            </div>
                        )}
                    </div>
                </div>

                {/* Footer */}
                <div className="p-6 pt-0">
                    <button
                        onClick={handleGenerate}
                        disabled={isGenerating}
                        className="w-full py-3 bg-pt-teal hover:bg-pt-teal/90 text-white rounded-xl font-bold flex items-center justify-center gap-2 transition-all disabled:opacity-70 disabled:cursor-not-allowed group active:scale-[0.98]"
                    >
                        {isGenerating ? (
                            <>
                                <Loader2 className="w-5 h-5 animate-spin" />
                                Crunching numbers...
                            </>
                        ) : (
                            <>
                                <FileText className="w-5 h-5 group-hover:scale-110 transition-transform" />
                                Generate Report
                            </>
                        )}
                    </button>
                    <p className="text-center text-xs text-pt-teal/50 mt-4">
                        Report will open in a print-optimized view.
                    </p>
                </div>
            </div>
        </div>
    );
}
