import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { CourtList, MatchQueue, PlayersModal } from "../queue";
import { hydratePersistedState, StorageUnavailableError } from "../../state/storage";
import { integrateRecords } from "../../state/entityOps";
import { readChangedRecords, readDeviceRecord, subscribeLiveClub } from "../../state/entityStore";
import { isE2EMode } from "../../state/e2eMode";
import config from "../../config";
import { computeTopTeams } from "../dashboard/utils/reports";
import { normalizeTeamsSettings } from "../../state/teamSettings";
import { resolveMatchSidesForDisplay } from "../../state/matchSides";
import {
	findCourtById,
	getPlayersOnCourt,
	listHasPlayerId,
	playerIdKey,
} from "../../state/courtPlayers";
import PlayerLeaderboardOverlay from "../leaderboard/components/PlayerLeaderboardOverlay";
import PlayerLeaderboardTop5Overlay from "../leaderboard/components/PlayerLeaderboardTop5Overlay";
import {
	buildPlayerLeaderboard,
	clearLeaderboardDisplay,
	LEADERBOARD_DISPLAY_EVENT,
	LEADERBOARD_DISPLAY_MODE,
	readLeaderboardDisplay,
	sliceLeaderboardTop,
} from "../leaderboard/utils/playerLeaderboard";

const DISPLAY_STATE_KEYS = [
	"teams",
	"settings.teamsModeEnabled",
	"settings.teams",
	"matches",
	"currentOpSession",
];
void DISPLAY_STATE_KEYS;

// Live clock component for the display header
function LiveClock() {
	const [now, setNow] = useState(new Date());
	useEffect(() => {
		const id = setInterval(() => setNow(new Date()), 1000);
		return () => clearInterval(id);
	}, []);
	return (
		<div className="text-right leading-none">
			<div className="text-4xl md:text-5xl font-condensed font-bold text-white tabular-nums drop-shadow-md">
				{now.toLocaleTimeString("en-PH", { hour: "2-digit", minute: "2-digit", second: "2-digit", hour12: true })}
			</div>
			<div className="text-base text-white/80 uppercase tracking-widest mt-2 font-medium">
				{now.toLocaleDateString("en-PH", { weekday: "short", month: "short", day: "numeric" })}
			</div>
		</div>
	);
}

export default function DisplayPage() {
	const [courts, setCourts] = useState([]);
	const [players, setPlayers] = useState([]);
	const [matchQueue, setMatchQueue] = useState([]);
	const [matches, setMatches] = useState([]);
	const [settings, setSettings] = useState(() => ({}));
	const [teams, setTeams] = useState(() => []);
	const [currentOpSession, setCurrentOpSession] = useState(null);
	const [openCourtId, setOpenCourtId] = useState(null);
	const [leaderboardUntil, setLeaderboardUntil] = useState(0);
	const [leaderboardMode, setLeaderboardMode] = useState(LEADERBOARD_DISPLAY_MODE.FULL);
	const [storageError, setStorageError] = useState(null);
	const [hydrating, setHydrating] = useState(true);
	const docRef = useRef({});
	const revMapRef = useRef(new Map());
	const lastCommitKeysRef = useRef(null);

	const hideLeaderboard = useCallback(() => {
		clearLeaderboardDisplay();
		setLeaderboardUntil(0);
	}, []);

	const closeDisplayModal = useCallback(() => {
		if (openCourtId && typeof window !== "undefined" && "BroadcastChannel" in window) {
			const bc = new BroadcastChannel("dink_manager");
			bc.postMessage({ type: "CLOSE_MODAL", courtId: openCourtId });
			bc.close();
		}
		setOpenCourtId(null);
	}, [openCourtId]);

	// Auto-close modal after 60 seconds
	useEffect(() => {
		if (!openCourtId) return;
		const timer = setTimeout(() => {
			closeDisplayModal();
		}, 60000);
		return () => clearTimeout(timer);
	}, [openCourtId, closeDisplayModal]);

	const publishDisplay = useCallback((doc) => {
		const next = doc || {};
		docRef.current = next;
		setCourts(Array.isArray(next.courts) ? next.courts : config.getDefaultCourts());
		setPlayers(next.players || []);
		setMatchQueue(next.matchQueue || []);
		setMatches(next.matches || []);
		setSettings(next.settings || {});
		setTeams(Array.isArray(next.teams) ? next.teams : []);
		setCurrentOpSession(next.currentOpSession || null);
		if (isE2EMode() && typeof window !== "undefined") {
			window.__sd = window.__sd || {};
			window.__sd.getDisplaySnapshot = () => docRef.current;
			window.__sd.displayReady = true;
		}
	}, []);

	const applyOverlayRecord = useCallback(async () => {
		const row = await readDeviceRecord("leaderboardDisplay");
		if (row?.data) {
			const until = Number(row.data.until) || 0;
			setLeaderboardUntil(until > Date.now() ? until : 0);
			setLeaderboardMode(
				row.data.mode === LEADERBOARD_DISPLAY_MODE.TOP5
					? LEADERBOARD_DISPLAY_MODE.TOP5
					: LEADERBOARD_DISPLAY_MODE.FULL
			);
			return;
		}
		const savedDisplay = readLeaderboardDisplay();
		if (savedDisplay.until > Date.now()) {
			setLeaderboardUntil(savedDisplay.until);
			setLeaderboardMode(savedDisplay.mode);
		}
	}, []);

	useEffect(() => {
		let cancelled = false;
		setHydrating(true);
		setStorageError(null);
		(async () => {
			try {
				const saved = await hydratePersistedState();
				if (cancelled || !saved) return;
				Object.entries(saved.entityRevs || {}).forEach(([key, rev]) => {
					revMapRef.current.set(key, Number(rev) || 0);
				});
				publishDisplay(saved);
				await applyOverlayRecord();
				if (!cancelled) setHydrating(false);
			} catch (err) {
				console.error("Display failed to hydrate from IndexedDB", err);
				if (!cancelled) {
					setStorageError(
						err instanceof StorageUnavailableError
							? err.message
							: "Could not load display data from this browser. Check that site data is allowed, then reload."
					);
					setHydrating(false);
				}
			}
		})();
		return () => {
			cancelled = true;
		};
	}, [applyOverlayRecord, publishDisplay]);

	useEffect(() => {
		const prevZoom = document.body.style.zoom;
		return () => {
			document.body.style.zoom = prevZoom || "100%";
			document.body.style.overflowX = "auto";
		};
	}, []);

	useEffect(() => {
		let cancelled = false;
		const refreshFromIdb = (keys) => {
			readChangedRecords(keys)
				.then((fresh) => {
					if (cancelled || !fresh) return;
					const integrated = integrateRecords({
						committed: docRef.current,
						live: docRef.current,
						records: fresh.records,
						tombstones: fresh.tombstones,
						revMap: revMapRef.current,
						pendingKeys: new Set(),
					});
					if (integrated.changed) publishDisplay(integrated.doc);
					const watchOverlay = !Array.isArray(keys) || keys.includes("device:leaderboardDisplay");
					if (watchOverlay) applyOverlayRecord();
				})
				.catch(() => {});
		};
		const onFocus = () => refreshFromIdb();
		const onPageShow = () => refreshFromIdb();
		window.addEventListener("focus", onFocus);
		window.addEventListener("pageshow", onPageShow);
		const unsubscribe = subscribeLiveClub((message) => {
			lastCommitKeysRef.current = message?.keys || null;
			refreshFromIdb(message?.keys);
		});

		let bc;
		if ("BroadcastChannel" in window) {
			bc = new BroadcastChannel("dink_manager");
			bc.onmessage = (msg) => {
				const { type, courtId } = msg?.data || {};
				if (type === "OPEN_MODAL") {
					setOpenCourtId(courtId ?? null);
					refreshFromIdb(lastCommitKeysRef.current || undefined);
				}
				if (type === "CLOSE_MODAL") setOpenCourtId(null);
				// STATE_UPDATE on the old channel is ignored.
				if (type === LEADERBOARD_DISPLAY_EVENT) {
					const until = Number(msg?.data?.until);
					const mode = msg?.data?.mode === LEADERBOARD_DISPLAY_MODE.TOP5
						? LEADERBOARD_DISPLAY_MODE.TOP5
						: LEADERBOARD_DISPLAY_MODE.FULL;
					setLeaderboardUntil(Number.isFinite(until) && until > Date.now() ? until : 0);
					setLeaderboardMode(mode);
					applyOverlayRecord();
				}
			};
		}

		return () => {
			cancelled = true;
			unsubscribe();
			window.removeEventListener("focus", onFocus);
			window.removeEventListener("pageshow", onPageShow);
			if (bc) bc.close();
		};
	}, [applyOverlayRecord, publishDisplay]);

	const teamsSettingsNorm = useMemo(() => normalizeTeamsSettings(settings?.teams), [settings?.teams]);

	const sessionTopTeams = useMemo(() => {
		const started = currentOpSession?.startedAt;
		if (!started || !settings?.teamsModeEnabled || teamsSettingsNorm.showTopTeamsOnDisplay === false)
			return [];
		const rows = computeTopTeams(matches, started, teamsSettingsNorm.topTeamsRankingMode || "winsFirst");
		return rows.map((r) => ({
			...r,
			displayName:
				teams.find((t) => String(t.id) === String(r.teamId))?.name ||
				(r.teamId === "__unassigned__" ? teamsSettingsNorm.unassignedLabel || "Unassigned" : `Team`),
			color: teams.find((t) => String(t.id) === String(r.teamId))?.color || "#94A3B8",
		}));
	}, [
		matches,
		currentOpSession?.startedAt,
		settings?.teamsModeEnabled,
		teams,
		teamsSettingsNorm,
	]);

	const selectedCourt = findCourtById(courts, openCourtId);
	const selectedMatch =
		selectedCourt?.currentMatchId != null
			? matches.find((m) => playerIdKey(m.id) === playerIdKey(selectedCourt.currentMatchId))
			: null;
	const courtTeamMeta =
		selectedMatch?.teamMeta && typeof selectedMatch.teamMeta === "object"
			? selectedMatch.teamMeta
			: null;
	const selectedSides = selectedMatch ? resolveMatchSidesForDisplay(selectedMatch) : null;
	const onCourt = selectedCourt ? getPlayersOnCourt(selectedCourt, players) : [];
	const selectedPlayers = onCourt.map((p) => ({
		...p,
		team: selectedSides?.green?.players?.some((id) => playerIdKey(id) === playerIdKey(p.id))
			? "green"
			: selectedSides?.blue?.players?.some((id) => playerIdKey(id) === playerIdKey(p.id))
				? "blue"
				: listHasPlayerId(selectedCourt?.teamGreen, p.id)
					? "green"
					: listHasPlayerId(selectedCourt?.teamBlue, p.id)
						? "blue"
						: null,
	}));

	const leaderboardRows = useMemo(
		() => buildPlayerLeaderboard(players, matches),
		[players, matches]
	);

	if (storageError) {
		return (
			<div className="min-h-screen flex flex-col items-center justify-center bg-pt-navy text-white px-6 text-center gap-3">
				<p className="text-lg font-semibold">Display storage unavailable</p>
				<p className="text-sm text-white/80 max-w-md">{storageError}</p>
				<p className="text-xs text-white/60">Allow site data on the operator machine, then reload this window.</p>
			</div>
		);
	}

	if (hydrating) {
		return (
			<div className="min-h-screen flex items-center justify-center bg-pt-navy text-white/70 text-sm">
				Loading display…
			</div>
		);
	}

	return (
		<div className="min-h-screen bg-display p-4 overflow-hidden flex flex-col">

			{/* ─── Header ─────────────────────────────────────────── */}
			<header className="flex items-center justify-between mb-5 px-2">
				{/* Brand */}
				<div className="flex items-center gap-5">
					<img
						src={config.assetPath("logo.png")}
						alt={config.name}
						className="h-16 md:h-24 w-auto object-contain"
					/>
					<div className="flex flex-col leading-none">
						<span className="text-2xl md:text-4xl text-white font-bold tracking-wide truncate max-w-[40vw]">
							{config.name}
						</span>
						<span className="text-[10px] text-[#C9A582] uppercase tracking-[0.3em] mt-1 font-medium">
							{config.tagline || "Sports Center"}
						</span>
					</div>
				</div>

				{/* Right: Live clock */}
				<LiveClock />
			</header>

			{/* Thin teal divider */}
			<div className="h-px bg-gradient-to-r from-transparent via-pt-orange/40 to-transparent mb-5 mx-2" />

			{/* ─── Main Content ────────────────────────────────────── */}
			<div className="flex-1 grid grid-cols-12 gap-5 min-h-0">

				{/* ╔══════════════╗ Left Column: Match Queue + Top 3 */}
				<div className="col-span-3 flex flex-col gap-4 min-h-0">

					{/* Match Queue */}
					<div className="flex flex-col bg-pt-dark-card rounded-2xl overflow-hidden border border-pt-dark-border shadow-2xl" style={{ flex: '3 1 0' }}>
						{/* Queue header strip */}
						<div className="px-5 py-4 border-b border-pt-dark-border">
							<h2 className="text-lg font-display font-bold text-white uppercase tracking-widest">
								Match Queue
							</h2>
							<p className="text-[10px] text-pt-orange/60 uppercase tracking-wider mt-0.5">Upcoming</p>
						</div>
						<div className="flex-1 overflow-y-auto p-3 custom-scrollbar-dark">
							<MatchQueue
								courts={courts}
								players={players}
								queue={matchQueue || []}
								readOnly
								onAddQueue={() => { }}
								onRemoveQueue={() => { }}
								onRemoveFromQueue={() => { }}
								onSendQueueToCourt={() => { }}
								onAutoBuild={() => { }}
								variant="display"
								teamsModeEnabled={settings?.teamsModeEnabled}
								teams={teams}
								teamsSettings={teamsSettingsNorm}
							/>
						</div>
					</div>

					{/* Client leaderboard: Teams mode -> session top teams; else player win rates */}
					{(() => {
						if (settings?.teamsModeEnabled && teamsSettingsNorm.showTopTeamsOnDisplay !== false && sessionTopTeams.length > 0) {
							const showN = 1 + (teamsSettingsNorm.topTeamsRunnerUpCount ?? 2);
							const slice = sessionTopTeams.slice(0, showN);
							const medals = ["🥇", "🥈", "🥉"];
							const isNight = new Date().getHours() >= 18;
							const cardTitle = isNight ? "Team of the Night" : "Team of the Day";
							return (
								<>
									<style>{`
										@keyframes chillGlow {
											0%, 100% { box-shadow: 0 0 8px 2px rgba(255,165,0,0.25), 0 0 18px 4px rgba(255,100,0,0.12); }
											50% { box-shadow: 0 0 18px 6px rgba(255,165,0,0.55), 0 0 36px 10px rgba(255,100,0,0.28); }
										}
									`}</style>
									<div className="bg-pt-dark-card rounded-2xl border border-pt-dark-border shadow-2xl overflow-hidden" style={{ flex: "2 1 0" }}>
										<div className="px-5 py-3 border-b border-pt-dark-border flex items-center gap-2">
											<span>🏆</span>
											<h2 className="text-sm font-display font-bold text-white uppercase tracking-widest">{cardTitle}</h2>
										</div>
										<div className="flex flex-col gap-2 p-4">
											{slice.map((entry, idx) => {
												const pct = Math.round(entry.winPct * 100);
												const isTop = idx === 0;
												return (
													<div
														key={entry.teamId}
														className="flex items-center gap-3 rounded-xl px-3 py-2"
														style={{
															background: isTop ? "rgba(255,165,0,0.08)" : "rgba(255,255,255,0.03)",
															border: isTop ? "1px solid rgba(255,165,0,0.4)" : "1px solid rgba(255,255,255,0.05)",
															animation: isTop ? "chillGlow 2.5s ease-in-out infinite" : "none",
														}}
													>
														<span className="text-xl shrink-0">{medals[idx] || "•"}</span>
														<span
															className="w-3 h-3 rounded-full shrink-0"
															style={{ backgroundColor: entry.color }}
														/>
														<span
															className="font-condensed font-black uppercase truncate flex-1"
															style={{
																fontSize: "clamp(0.85rem, 1.6vw, 1.2rem)",
																color: isTop ? "#FFD700" : "rgba(255,255,255,0.85)",
															}}
														>
															{entry.displayName}
														</span>
														<span className="text-[10px] text-white/50 shrink-0">{entry.wins}W</span>
														<span className="font-condensed font-black shrink-0" style={{ color: isTop ? "#FFD700" : "rgba(255,255,255,0.5)" }}>
															{pct}%
														</span>
													</div>
												);
											})}
										</div>
									</div>
								</>
							);
						}

						const top3 = sliceLeaderboardTop(leaderboardRows, 3);
						const isNight = new Date().getHours() >= 18;
						const cardTitle = isNight ? 'Player of the Night' : 'Player of the Day';
						const medals = ['🥇', '🥈', '🥉'];
						return (
							<>
							<style>{`
								@keyframes chillGlow {
									0%, 100% { box-shadow: 0 0 8px 2px rgba(255,165,0,0.25), 0 0 18px 4px rgba(255,100,0,0.12); }
									50% { box-shadow: 0 0 18px 6px rgba(255,165,0,0.55), 0 0 36px 10px rgba(255,100,0,0.28); }
								}
							`}</style>
							<div className="bg-pt-dark-card rounded-2xl border border-pt-dark-border shadow-2xl overflow-hidden" style={{ flex: '2 1 0' }}>
								<div className="px-5 py-3 border-b border-pt-dark-border flex items-center gap-2">
									<span>🔥</span>
									<h2 className="text-sm font-display font-bold text-white uppercase tracking-widest">{cardTitle}</h2>
								</div>
								<div className="flex flex-col gap-2 p-4">
									{top3.length === 0 ? (
										<p className="text-center text-white/20 text-xs uppercase tracking-widest py-4">No ranked players yet.</p>
									) : top3.map((entry, idx) => {
										const isTop = entry.rank === 1;
										return (
											<div key={entry.id || entry.name} className="flex items-center gap-3 rounded-xl px-3 py-2"
												style={{
													background: isTop ? 'rgba(255,165,0,0.08)' : 'rgba(255,255,255,0.03)',
													border: isTop ? '1px solid rgba(255,165,0,0.4)' : '1px solid rgba(255,255,255,0.05)',
													borderRadius: '0.75rem',
													animation: isTop ? 'chillGlow 2.5s ease-in-out infinite' : 'none',
												}}>
												<span className="text-xl shrink-0">{medals[idx]}</span>
												<span
													className="font-condensed font-black uppercase truncate flex-1"
													style={{
														fontSize: 'clamp(0.9rem, 1.8vw, 1.3rem)',
														color: isTop ? '#FFD700' : 'rgba(255,255,255,0.85)',
														textShadow: isTop ? '0 0 10px rgba(255,200,0,0.8)' : 'none',
													}}
												>
													{isTop ? '🔥 ' : ''}{entry.name}
												</span>
												<span className="font-condensed font-black shrink-0" style={{ fontSize: 'clamp(0.85rem, 1.5vw, 1.1rem)', color: isTop ? '#FFD700' : 'rgba(255,255,255,0.5)' }}>
													{entry.wins}W
												</span>
											</div>
										);
									})}
								</div>
							</div>
							</>
						);
					})()}

				</div>

				{/* ╔══════════════════════════════╗ Live Courts (Right ~75%) */}
				<div className="col-span-9 flex flex-col h-full">

					{/* Courts section label */}
					<div className="flex items-center gap-3 mb-4 px-1">
						<div className="h-5 w-1 bg-pt-orange rounded-full" />
						<h2 className="text-xl font-display font-bold text-white uppercase tracking-widest">
							Live Courts
						</h2>
						{/* live indicator dot */}
						<span className="flex items-center gap-1.5 ml-auto">
							<span className="h-2 w-2 rounded-full bg-red-500 animate-pulse" />
							<span className="text-[10px] text-white/40 uppercase tracking-widest font-display">Live</span>
						</span>
					</div>

					{/* Court cards grid — dynamic layout based on court count */}
					{(() => {
						const n = courts.length;
						let cols, rows;
						if (n <= 1) { cols = 1; rows = 1; }
						else if (n <= 2) { cols = 2; rows = 1; }
						else if (n <= 4) { cols = 2; rows = 2; }
						else if (n <= 6) { cols = 3; rows = 2; }
						else if (n <= 9) { cols = 3; rows = 3; }
						else { cols = 4; rows = Math.ceil(n / 4); }
						return (
							<div
								className="flex-1 min-h-0"
								style={{
									display: 'grid',
									gap: '0.75rem',
									gridTemplateColumns: `repeat(${cols}, minmax(0, 1fr))`,
									gridTemplateRows: `repeat(${rows}, minmax(0, 1fr))`,
								}}
							>
								<CourtList
									courts={courts}
									players={players}
									matches={matches}
									teamsModeEnabled={settings?.teamsModeEnabled}
									teams={teams}
									teamsSettings={teamsSettingsNorm}
									onAssign={() => { }}
									onRemove={() => { }}
									onUnlockCourt={() => { }}
									onRemoveCourt={() => { }}
									onUpdateCourtName={() => { }}
									onSetTeams={() => { }}
									onCompleteMatch={() => { }}
									readOnly
									compact
									className="contents"
									variant="display"
								/>
							</div>
						);
					})()}
				</div>

				{/* Players Modal */}
				<PlayersModal
					open={openCourtId != null}
					onClose={closeDisplayModal}
					courtName={selectedCourt?.name || ""}
					players={selectedPlayers}
					isReadOnly
					variant="display"
					teamsModeEnabled={settings?.teamsModeEnabled}
					teams={teams}
					teamsSettings={teamsSettingsNorm}
					courtTeamMeta={courtTeamMeta}
				/>
			</div>

			{/* Footer watermark */}
			<p className="text-center text-[10px] text-white/15 font-mono mt-4 tracking-widest uppercase">
				Powered by Dink Manager
			</p>

			{leaderboardUntil > Date.now() && leaderboardMode === LEADERBOARD_DISPLAY_MODE.TOP5 && (
				<PlayerLeaderboardTop5Overlay
					rows={sliceLeaderboardTop(leaderboardRows, 5)}
					until={leaderboardUntil}
					onClose={hideLeaderboard}
				/>
			)}
			{leaderboardUntil > Date.now() && leaderboardMode !== LEADERBOARD_DISPLAY_MODE.TOP5 && (
				<PlayerLeaderboardOverlay
					rows={leaderboardRows}
					until={leaderboardUntil}
					onClose={hideLeaderboard}
				/>
			)}
		</div>
	);
}
