import { formatBookingCreatedDate, sortBookingsByCreatedAtDesc } from "./bookingHistoryFormat";

/** Local YYYY-MM-DD of the earliest play slot. Missing slots yield "". */
export function earliestRentalYmd(booking, slotsById = {}) {
  const slots = (booking?.slotIds || [])
    .map((id) => slotsById[id])
    .filter((slot) => slot && slot.status !== "CANCELLED" && slot.date);
  if (!slots.length) return "";
  slots.sort((a, b) => {
    const dateCmp = String(a.date).slice(0, 10).localeCompare(String(b.date).slice(0, 10));
    if (dateCmp !== 0) return dateCmp;
    return (Number(a.startTime) || 0) - (Number(b.startTime) || 0);
  });
  return String(slots[0].date).slice(0, 10);
}

export function bookingCreatedMonthKey(createdAt) {
  return formatBookingCreatedDate(createdAt).slice(0, 7);
}

/**
 * basis: "rental" (play month) | "booking" (created month) | "both" (either).
 * Rental month uses the earliest slot so a multi-day rental counts once.
 */
export function rentalMatchesDateBasis(booking, slotsById, monthKey, basis = "rental") {
  if (!monthKey) return false;
  const rentalMonth = earliestRentalYmd(booking, slotsById).slice(0, 7);
  const bookedMonth = bookingCreatedMonthKey(booking?.createdAt || booking?.created_at);
  if (basis === "booking") return bookedMonth === monthKey;
  if (basis === "both") return bookedMonth === monthKey || rentalMonth === monthKey;
  return rentalMonth === monthKey;
}

export function filterRentalHistoryBookings(bookings, slotsById, monthKey, basis = "rental") {
  const list = (Array.isArray(bookings) ? bookings : []).filter((booking) =>
    rentalMatchesDateBasis(booking, slotsById, monthKey, basis)
  );
  return sortBookingsByCreatedAtDesc(list);
}

/** Live search on renter name or rental code. Blank query matches everything. */
export function rentalRowMatchesSearch(row, query) {
  const q = String(query || "").trim().toLowerCase();
  if (!q) return true;
  const name = String(row?.renterName || "").toLowerCase();
  const code = String(row?.bookingRef || "").toLowerCase();
  return name.includes(q) || code.includes(q);
}

/** Local month bounds for slot dates and a created-at window [start, next month). */
export function monthBounds(monthKey) {
  const [y, m] = String(monthKey || "").split("-").map(Number);
  if (!y || !m || m < 1 || m > 12) return null;
  const start = new Date(y, m - 1, 1);
  const end = new Date(y, m, 0);
  const next = new Date(y, m, 1);
  return {
    slotStart: start.toLocaleDateString("en-CA"),
    slotEnd: end.toLocaleDateString("en-CA"),
    createdStart: start.toISOString(),
    createdEnd: next.toISOString(),
  };
}
