/** YYYY-MM from a Date in local time. */
export function getMonthKey(date) {
  if (!date || Number.isNaN(date.getTime())) return "";
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, "0");
  return `${y}-${m}`;
}

export function monthKeyFromTimestamp(ts) {
  if (ts == null || ts === "") return "";
  const date = new Date(ts);
  return getMonthKey(date);
}

/** Start month and end month so a session closed this month still appears even if it started earlier. */
export function getSessionMonthKeys(session) {
  const keys = new Set();
  const startKey = monthKeyFromTimestamp(session?.startedAt);
  const endKey = monthKeyFromTimestamp(session?.endedAt);
  if (startKey) keys.add(startKey);
  if (endKey) keys.add(endKey);
  return keys;
}

export function sessionBelongsToMonth(session, monthKey) {
  if (!monthKey) return false;
  const keys = getSessionMonthKeys(session);
  if (keys.has(monthKey)) return true;
  if (keys.size === 0) return monthKey === getMonthKey(new Date());
  return false;
}

export function otherSessionMonthKeys(sessions = [], currentMonthKey) {
  const keys = new Set();
  (Array.isArray(sessions) ? sessions : []).forEach((session) => {
    getSessionMonthKeys(session).forEach((key) => {
      if (key && key !== currentMonthKey) keys.add(key);
    });
  });
  return Array.from(keys).sort().reverse();
}
