import { useEffect, useRef } from "react";

/**
 * Automatically logs out the user if no activity is detected for a set duration.
 * @param {Object} params
 * @param {string|null} params.userRole - Current user role. Only activates if role is 'admin'.
 * @param {Function} params.logout - Logout function to trigger.
 * @param {number} [params.timeoutMs=3600000] - Timeout in milliseconds (default 1 hour).
 */
export default function useInactivityTimer({ userRole, logout, timeoutMs = 3600000 }) {
    const lastActivityRef = useRef(Date.now());
    const timerRef = useRef(null);

    useEffect(() => {
        // If not admin, do nothing
        if (userRole !== "admin") return;

        const handleActivity = () => {
            lastActivityRef.current = Date.now();
        };

        // Events to track
        const events = ["mousedown", "mousemove", "keydown", "scroll", "touchstart"];

        // Throttle event listeners to avoid performance hit? 
        // Actually, simply updating a ref is very cheap.
        events.forEach((event) => {
            window.addEventListener(event, handleActivity);
        });

        // Check every minute
        timerRef.current = setInterval(() => {
            const now = Date.now();
            if (now - lastActivityRef.current > timeoutMs) {
                console.log("Session timeout: Logging out due to inactivity.");
                logout();
            }
        }, 60 * 1000); // Check every 1 minute

        return () => {
            events.forEach((event) => {
                window.removeEventListener(event, handleActivity);
            });
            if (timerRef.current) clearInterval(timerRef.current);
        };
    }, [userRole, logout, timeoutMs]);
}
