export const ADMIN_AUDIT_ACTOR = "Admin";
export const STAFF_AUDIT_ACTOR_FALLBACK = "Staff";

export function resolveAuditActor(userRole, staffName) {
  if (userRole === "admin") return ADMIN_AUDIT_ACTOR;
  const name = typeof staffName === "string" ? staffName.trim() : "";
  return name || STAFF_AUDIT_ACTOR_FALLBACK;
}

export function staffNameForRole(userRole, staffName) {
  if (userRole !== "staff") return "";
  return typeof staffName === "string" ? staffName.trim() : "";
}
