import { useEffect, useState } from 'react';
import { fetchRentalQuote } from '../../../common/api/rentalQuote';

export default function useRentalQuote(slots, renter, bookingId, enabled, pricingRevision) {
  const key = JSON.stringify({ slots: slots.map(({ courtId, date, startTime, endTime, manualPrice }) => ({ courtId, date, startTime, endTime, manualPrice })), renter, bookingId, pricingRevision });
  const [attempt, setAttempt] = useState(0);
  const [result, setResult] = useState(null);
  const [error, setError] = useState(null);
  useEffect(() => {
    if (!enabled || !slots.length) return;
    const controller = new AbortController();
    const input = JSON.parse(key);
    const timer = setTimeout(async () => {
      try {
        const quote = await fetchRentalQuote(input.slots, input.renter, input.bookingId, controller.signal);
        if (!controller.signal.aborted) { setResult({ key, quote, attempt }); setError(null); }
      } catch (err) { if (!controller.signal.aborted) setError({ key, attempt, message: err.message }); }
    }, 150);
    return () => { clearTimeout(timer); controller.abort(); };
  }, [key, enabled, slots.length, attempt]);
  const quote = result?.key === key && result.attempt === attempt ? result.quote : null;
  const message = error?.key === key && error.attempt === attempt ? error.message : null;
  return { quote, error: message, retry: () => setAttempt(value => value + 1), pending: enabled && (!quote || !!message) };
}
