export default class BaseService {
  constructor(baseURL, defaultHeaders = {}) {
    this.baseURL = baseURL?.replace(/\/$/, "") || "";
    this.defaultHeaders = defaultHeaders;
  }

  async request(path, { method = "GET", headers = {}, query = undefined, body = undefined } = {}) {
    const url = new URL((path || "").replace(/^[#?&]/, ""), this.baseURL || window.location.origin);
    if (query && typeof query === "object") {
      Object.entries(query).forEach(([k, v]) => {
        if (v === undefined || v === null) return;
        url.searchParams.set(k, String(v));
      });
    }

    const init = {
      method,
      headers: {
        "Content-Type": body ? "application/json" : undefined,
        ...this.defaultHeaders,
        ...headers,
      },
      body: body ? JSON.stringify(body) : undefined,
    };

    // Clean undefined headers
    Object.keys(init.headers).forEach((k) => {
      if (init.headers[k] === undefined) delete init.headers[k];
    });

    const res = await fetch(url.toString(), init);
    const text = await res.text();
    let data;
    try {
      data = text ? JSON.parse(text) : null;
    } catch {
      data = text;
    }
    if (!res.ok) {
      const err = new Error(`HTTP ${res.status}: ${res.statusText}`);
      err.status = res.status;
      err.data = data;
      throw err;
    }
    return data;
  }
}

